--   id 1001~ : 데모 레시피 중 이름이 겹치지 않는 23건 — code 는 데모 id
-- ingredient_type: MAIN 필수 · SUB 선택 · SEASONING 기본 양념 (추천 계산에서 있는 것으로 본다)
-- storage_days: 만든 요리 냉장 보관 일수 (데모 v8 DISH_DAYS, 분류가 없으면 이름으로 추정)
-- 생성: ai/data/build_seed.py (recipes.json + master_data.json). 직접 고치지 말고 새 V 파일로 덧붙인다.
-- =====================================================================

INSERT INTO recipe (id, code, title, description, cook_time_min, difficulty, servings, category, cuisine, kcal, source, storage_days) VALUES
(1, 'r1', '나물비빔밥', '육수로 지은 밥에 야채를 듬뿍 넣은 영양만점 나물비빔밥!', 60, '보통', 4, '밥', '한식', '580Kcal', '농림수산식품교육문화정보원', 1),
(2, 'r2', '오곡밥', '정월대보름에 먹던 오곡밥! 영양을 한그릇에 담았습니다.', 60, '보통', 4, '밥', '한식', '338Kcal', '농림수산식품교육문화정보원', 1),
(3, 'r3', '잡채밥', '잡채밥 한 그릇이면 오늘 저녁 끝! 입 맛 없을 때 먹으면 그만이지요~', 30, '보통', 4, '밥', '중국', '520Kcal', '농림수산식품교육문화정보원', 1),
(4, 'r4', '콩나물밥', '다이어트에 으뜸인 콩나물밥. 밥 물 넣을때 평소보다 적게 넣는거 잊지마세요!', 40, '초보환영', 4, '밥', '한식', '401Kcal', '농림수산식품교육문화정보원', 1),
(5, 'r5', '약식', '집에서도 쉽게 만들어 맛있게 먹을 수 있답니다. 어려워 마시고 만들어 보세요~!', 60, '보통', 4, '떡/한과', '한식', '259Kcal', '농림수산식품교육문화정보원', 2),
(6, 'r6', '호박죽', '호박죽 한 그릇이면 하루가 든든하답니다.', 30, '보통', 4, '밥', '한식', '115Kcal', '농림수산식품교육문화정보원', 1),
(7, 'r7', '흑임자죽', '검은깨를 갈아서 만든 고소함이 가득한 흑임자죽. 남녀노소 모두 사랑하는 맛!', 25, '보통', 4, '밥', '한식', '450Kcal', '농림수산식품교육문화정보원', 1),
(8, 'r8', '카레라이스', '향긋한 카레향이 너무 좋지요. 누구나 좋아하는 만들기도 간편한 음식입니다.', 30, '초보환영', 4, '밥', '동남아시아', '650Kcal', '농림수산식품교육문화정보원', 1),
(9, 'r9', '오므라이스', '각종 채소를 계란 속에 꼭꼭 숨겨 편식하는 아이들도 맛있게 먹어요~', 30, '초보환영', 4, '밥', '서양', '630Kcal', '농림수산식품교육문화정보원', 1),
(10, 'r10', '감자수제비', '쫀득쫀득한 수제비와 담백한 맛의 감자가 이뤄내는 하모니!', 60, '초보환영', 4, '만두/면류', '한식', '410Kcal', '농림수산식품교육문화정보원', 1),
(11, 'r11', '냉면', '더운 여름, 살얼음 동동 띄운 시원한 냉면 한그릇 생각나시죠~', 50, '보통', 4, '만두/면류', '한식', '630Kcal', '농림수산식품교육문화정보원', 1),
(12, 'r12', '동치미막국수', '시원한 동치미에 쫄깃한 국수를 말아서 만들어보세요.', 30, '보통', 4, '만두/면류', '한식', '400Kcal', '농림수산식품교육문화정보원', 1),
(13, 'r13', '열무김치냉면', '맛있게 담근 열무김치에 냉면을 말아 먹어 보세요~ 새콤달콤 끝내줍니다!', 25, '보통', 4, '만두/면류', '한식', '625Kcal', '농림수산식품교육문화정보원', 1),
(14, 'r14', '채소국수', '갖가지 야채를 듬뿍 넣어서 만든 요리로 출출할 때 간식거리로 아주 좋답니다.', 30, '초보환영', 2, '만두/면류', '한식', '460Kcal', '농림수산식품교육문화정보원', 1),
(15, 'r15', '해물국수', '해물로 시원한 국물에 국수를 말아 드셔보세요~', 40, '보통', 4, '만두/면류', '한식', '530Kcal', '농림수산식품교육문화정보원', 1),
(16, 'r16', '만둣국', '만두를 예쁘게 만들면 이쁜 딸을 낳는다고 하죠? 가족들과 오손도손 맛있는 만두국 만들어 드셔보세요~', 40, '보통', 4, '만두/면류', '한식', '540Kcal', '농림수산식품교육문화정보원', 1),
(17, 'r17', '다시마냉국', '철분과 무기질이 풍부한 다시마로 피부건강을 지켜보세요~', 20, '초보환영', 4, '국', '한식', '63Kcal', '농림수산식품교육문화정보원', 3),
(18, 'r18', '두부국', '부드러운 두부로 맛나는 두부국을 끓여 단백함을 맛보세요.', 40, '초보환영', 4, '국', '한식', '120Kcal', '농림수산식품교육문화정보원', 3),
(19, 'r19', '두부조개탕', '국물이 정말 시원해서 속풀이 식단으로도 안성맞춤!', 30, '초보환영', 4, '국', '한식', '130Kcal', '농림수산식품교육문화정보원', 3),
(20, 'r20', '무맑은국', '고향의 맛을 느낄 수 있는 무국. 밥한그릇 뚝딱이죠!', 30, '초보환영', 4, '국', '한식', '75Kcal', '농림수산식품교육문화정보원', 3),
(21, 'r21', '미역국', '미역국은 철분이 풍부하게 함유된 음식이라 여자들에게 특히 좋은 음식이라 하지요.', 30, '초보환영', 4, '국', '한식', '95Kcal', '농림수산식품교육문화정보원', 3),
(22, 'r22', '미역냉국', '더운 여름, 새콤달콤 시원한 미역냉국으로 입맛을 살려보세요~', 30, '초보환영', 4, '국', '한식', '82Kcal', '농림수산식품교육문화정보원', 3),
(23, 'r23', '생태국', '생태국에 콩나물을 넣어주면 시원함이 배가 됩니다.', 30, '보통', 4, '국', '한식', '110Kcal', '농림수산식품교육문화정보원', 3),
(24, 'r24', '연어까르파치오', '독특한 바질향이 연어에 쏘옥~ 올리브오일로 한층 부드러운 연어회랍니다.', 30, '초보환영', 2, '나물/생채/샐러드', '이탈리아', '120Kcal', '농림수산식품교육문화정보원', 2),
(25, 'r25', '오이냉국', '아삭아삭한 오이와 새콤달콤한 냉국의 조화!', 20, '초보환영', 4, '국', '한식', '82Kcal', '농림수산식품교육문화정보원', 3),
(26, 'r26', '해산물샐러드', '시원한 해산물 샐러드~ 상큼한 레몬과 와인을 넣은 드레싱으로 깔끔하게~', 30, '보통', 2, '나물/생채/샐러드', '이탈리아', '180Kcal', '농림수산식품교육문화정보원', 2),
(27, 'r27', '재첩국', '재첩은 해감을 잘 한다음 사용하셔야 해요. 그래야 깔끔한 맛을 낼 수 있어요.', 30, '초보환영', 4, '국', '한식', '130Kcal', '농림수산식품교육문화정보원', 3),
(28, 'r28', '구운감자와도미구이', '감자의 고소함과 도미의 담백함이 어울리는 너무나도 깔끔한 맛의 음식이예요.', 60, '보통', 2, '구이', '이탈리아', '225Kcal', '농림수산식품교육문화정보원', 2),
(29, 'r29', '쇠고기산적', '고기와 버섯이 잘 어우러져 언제나 먹어도 질리지 않고 맛있어서 자주 생각나는 음식이죠~!', 40, '보통', 2, '구이', '한식', '320Kcal', '농림수산식품교육문화정보원', 2),
(30, 'r30', '쇠고기양송이볶음', '쫄깃하고 부드러운 쇠고기와 양송이의 만남! 향도 맛도 일품이예요~', 40, '보통', 4, '볶음', '한식', '210Kcal', '농림수산식품교육문화정보원', 2),
(31, 'r31', '팥국수', '팥죽으로만 먹던 팥을 국수로 먹어보세요. 국수가 새롭게 느껴진답니다.', 30, '보통', 4, '만두/면류', '한식', '692Kcal', '농림수산식품교육문화정보원', 1),
(32, 'r32', '죽순표고버섯볶음나물', '향이 좋은 죽순과 표고버섯을 같이 볶아 보세요. 입맛 살리는 음식이 될거에요.', 20, '보통', 4, '볶음', '중국', '105Kcal', '농림수산식품교육문화정보원', 2),
(33, 'r33', '부추표고버섯볶음', '향긋한 부추와 표고버섯을 같이 볶아보세요.', 30, '보통', 4, '볶음', '중국', '150Kcal', '농림수산식품교육문화정보원', 2),
(34, 'r34', '두부드레싱과 채소샐러드', '두부의 부드러운 촉감이 너무 좋네요. 물론 몸에도 좋은 추천건강드레싱이예요~', 30, '초보환영', 2, '나물/생채/샐러드', '퓨전', '91Kcal', '농림수산식품교육문화정보원', 2),
(35, 'r35', '콩나물무침', '아주 흔한 요리이지만,그 맛을 내는데도 비법이 있죠!', 20, '초보환영', 4, '밑반찬/김치', '한식', '82Kcal', '농림수산식품교육문화정보원', 4),
(36, 'r36', '우엉조림', '아삭한 우엉을 맛깔스러운 간장 양념으로 조려보세요~ 맛깔스러운 간단한 반찬, 만들어볼까요?', 30, '초보환영', 4, '조림', '한식', '75Kcal', '농림수산식품교육문화정보원', 4),
(37, 'r37', '바질토마토두부샐러드', '샐러드를 더욱 상큼하게 만들어주는 참빛고운 포도씨유로 요리에 상큼함을 더해보세요~', 20, '초보환영', 2, '나물/생채/샐러드', '서양', '147Kcal', '농림수산식품교육문화정보원', 2),
(38, 'r38', '멸치볶음', '고소하고 짭잘한 멸치볶음 하나면 밥 한공기 뚝딱이죠.', 20, '초보환영', 4, '볶음', '한식', '210Kcal', '농림수산식품교육문화정보원', 2),
(39, 'r39', '갈치무조림', '구이가 지겨우시다면 조림으로 즐겨보세요~ 무를 넣어 더 맛있습니다!', 40, '초보환영', 4, '조림', '한식', '220Kcal', '농림수산식품교육문화정보원', 4),
(40, 'r40', '닭불고기', '닭고기로 만든 불고기! 간장양념이 맛있어요~', 35, '보통', 4, '볶음', '한식', '360Kcal', '농림수산식품교육문화정보원', 2),
(41, 'r41', '두부다시마말이', '짭조롬하면서 단백한 두부다시다말이. 다이어트 음식으로 손색없지요.', 30, '보통', 2, '나물/생채/샐러드', '한식', '110Kcal', '농림수산식품교육문화정보원', 2),
(42, 'r42', '팥칼국수', '구수하고 담백한 팥칼국수~  걸쭉한 팥국물이 딱이예요!', 50, '보통', 2, '만두/면류', '한식', '469Kcal', '농림수산식품교육문화정보원', 1),
(43, 'r43', '콩나물잡채', '당면 대신 콩나물로 잡채를 만들어볼까요~', 30, '보통', 4, '나물/생채/샐러드', '한식', '175Kcal', '농림수산식품교육문화정보원', 2),
(44, 'r44', '양배추말이찜', '양배추에 다진고기와 두부를 으깨어 넣어 맛있게 쪄서 먹기좋은 크기로 썰어보세요~', 50, '보통', 4, '찜', '한식', '180Kcal', '농림수산식품교육문화정보원', 3),
(45, 'r45', '마늘장아찌', '마늘장아찌, 입맛 없을 때 드셔보세요~', 20, '초보환영', 4, '밑반찬/김치', '한식', '44Kcal', '농림수산식품교육문화정보원', 4),
(46, 'r46', '오징어불고기', '오징어로 불고기를 만들어 맛있게 드셔보세요~ 간단하면서도 쉽게 맛낼 수 있답니다.', 40, '보통', 4, '볶음', '한식', '320Kcal', '농림수산식품교육문화정보원', 2),
(47, 'r47', '생선탕수', '필수아미노산이 풍부한 생선을 탕수육에 응용해보세요. 생선을 못먹는 어린이들에게 더없이 좋답니다.', 40, '보통', 4, '튀김/커틀릿', '중국', '540Kcal', '농림수산식품교육문화정보원', 2),
(48, 'r48', '갈비구이', '영양 풍부한 갈비로 푸짐한 구이 한번 해볼까요?', 60, '보통', 4, '구이', '한식', '324Kcal', '농림수산식품교육문화정보원', 2),
(49, 'r49', '돈까스', '가장 흔한 요리를 가장 특별하게 먹을때 처럼 기분좋은 마음으로 돈까스를 만들어보세요!', 60, '보통', 2, '튀김/커틀릿', '일본', '560Kcal', '농림수산식품교육문화정보원', 2),
(50, 'r50', '갈비찜', '잔칫상에 갈비찜이 빠질 수 없죠!', 80, '보통', 4, '찜', '한식', '350Kcal', '농림수산식품교육문화정보원', 3),
(51, 'r51', '제육보쌈', '돼지고기로 보쌈요리를 해보세요... 배추속도 맛있게 양념하여 준비하구요', 60, '보통', 4, '찜', '한식', '300Kcal', '농림수산식품교육문화정보원', 3),
(52, 'r52', '홍합꼬치구이', '쫄깃한 홍합을 좀 더 맛있게 드시는 법~~ 항상 먹는 음식에도 살짝만 변형을 주면 새로움이 느껴진답니다.', 30, '보통', 4, '구이', '한식', '130Kcal', '농림수산식품교육문화정보원', 2),
(53, 'r53', '청국장찌개', '한국인의 입맛에 딱 맞는 구수한 청국장입니다!', 30, '초보환영', 4, '찌개/전골/스튜', '한식', '117Kcal', '농림수산식품교육문화정보원', 3),
(54, 'r54', '순두부찌개', '순두부의 연한 질감과 개운한 국물이 입안에서 술~술~넘어갑니다.', 25, '초보환영', 4, '찌개/전골/스튜', '한식', '133Kcal', '농림수산식품교육문화정보원', 3),
(55, 'r55', '동태찌개', '？끗이 손질한 생선을 넣어 시원한 동태찌개를 끓여보세요~', 40, '초보환영', 2, '찌개/전골/스튜', '한식', '125Kcal', '농림수산식품교육문화정보원', 3),
(56, 'r56', '김치찌개', '냉장고에 있는 김치로 얼큰한 김치찌개 끓여보세요. 김치는 단순한 듯 하지만 조리법에 따라 다양한 맛을 낼 수 있답니다.', 40, '초보환영', 4, '찌개/전골/스튜', '한식', '230Kcal', '농림수산식품교육문화정보원', 3),
(57, 'r57', '콩비지찌개', '구수한 냄새가 고향의 맛을 전해주네요. 옛날 엄마의 맛을 기억하면서 정성스럽게 끓여보세요.', 30, '보통', 4, '찌개/전골/스튜', '한식', '160Kcal', '농림수산식품교육문화정보원', 3),
(58, 'r58', '북어국', '개운한 북어국은 해장용으로도~ 소화가 잘 안되 속을 진정시켜줄 때에도 모두 좋은 요리랍니다.', 30, '초보환영', 4, '국', '한식', '123Kcal', '농림수산식품교육문화정보원', 3),
(59, 'r59', '유부초밥', '맛있게 조린 유부에 밥을 넣어 만든 초밥종류입니다', 20, '보통', 1, '도시락/간식', '일본', '560Kcal', '농림수산식품교육문화정보원', 1),
(60, 'r60', '오색주먹밥도시락', '오감만족 오색빛깔 주먹밥!', 30, '초보환영', 4, '도시락/간식', '한식', '385Kcal', '농림수산식품교육문화정보원', 1),
(61, 'r61', '해파리냉채', '쫄깃한 해파리로 새콤한 냉채요리를 해보세요. 손님초대 요리로 손색없는 입맛 당기는 요리입니다.', 40, '초보환영', 4, '나물/생채/샐러드', '한식', '82Kcal', '농림수산식품교육문화정보원', 2),
(62, 'r62', '통배추김치', '우리 식탁에서 꼭 빠져서는 안될 것이 바로 배추김치죠.', 90, '보통', 4, '밑반찬/김치', '한식', '50Kcal', '농림수산식품교육문화정보원', 4),
(63, 'r63', '열무김치', '아삭하게 씹히는 열무김치, 잘 익힌 국물 맛이 탄산음료에 버금간답니다.', 40, '보통', 4, '밑반찬/김치', '한식', '45Kcal', '농림수산식품교육문화정보원', 4),
(64, 'r64', '오이소박이', '아삭하게 씹히는 오이와 맛있는 양념의 환상의 조화!', 40, '보통', 4, '밑반찬/김치', '한식', '85Kcal', '농림수산식품교육문화정보원', 4),
(65, 'r65', '나박김치', '향긋한 미나리를 나박김치에 넣어 향도좋고 맛도좋은 개운한 물김치 드셔보세요. 소화제가 필요없답니다.', 35, '보통', 4, '밑반찬/김치', '한식', '45Kcal', '농림수산식품교육문화정보원', 4),
(66, 'r66', '총각김치', '뜨거운 밥과 총각김치가 너무 잘 어울리지요.', 60, '보통', 4, '밑반찬/김치', '한식', '32Kcal', '농림수산식품교육문화정보원', 4),
(67, 'r67', '굴깍두기', '무에 굴을 넣어 김치를 담궈보세요. 굴의 풍부한 영양과 무의 개운한 맛이 함쳐져 굴깍두기 하나로 밥 한그릇 뚝딱입니다.', 40, '보통', 4, '밑반찬/김치', '한식', '43Kcal', '농림수산식품교육문화정보원', 4),
(68, 'r68', '동치미', '동치미로 시원한 국물 내어 겨울철 야식으로 이용해보세요. 이보다 더 맛있을 순 없을겁니다.', 40, '보통', 4, '밑반찬/김치', '한식', '35Kcal', '농림수산식품교육문화정보원', 4),
(69, 'r69', '갓김치', '물에 밥을 말아 갓김치를 얹어 먹으면 밥도둑이 따로 없답니다. 씁쓸한 맛이 매력인 갓김치! 만들어 보세요~', 30, '보통', 4, '밑반찬/김치', '한식', '41Kcal', '농림수산식품교육문화정보원', 4),
(70, 'r70', '꽃게찌개', '알이 가득 찬 꽃게로 얼큰하고 시원한 탕요리를 해보세요~', 40, '어려움', 4, '찌개/전골/스튜', '한식', '158Kcal', '농림수산식품교육문화정보원', 3),
(71, 'r71', '감자탕', '얼큰한 국물에 양념이 잘 베인 감자와 돼지고기가 입에서 술술 넘어갑니다.', 60, '보통', 4, '찌개/전골/스튜', '한식', '455Kcal', '농림수산식품교육문화정보원', 3),
(72, 'r72', '아구탕', '아구찜과는 또다른 매력, 아구탕 대령이오~', 30, '초보환영', 4, '국', '한식', '178Kcal', '농림수산식품교육문화정보원', 3),
(73, 'r73', '조기매운탕', '조기로 구이요리만 하셨다구요? 이번에는 매운탕으로 끓여보세요. 조기의 또다른 맛을 느끼실 수 있답니다.', 30, '초보환영', 4, '찌개/전골/스튜', '한식', '156Kcal', '농림수산식품교육문화정보원', 3),
(74, 'r74', '알탕', '씹히는 맛이 독특한 알이 듬뿍 들어간 얼큰하고 시원한 알탕!', 30, '보통', 4, '찌개/전골/스튜', '한식', '140Kcal', '농림수산식품교육문화정보원', 3),
(75, 'r75', '우거지된장찌개', '비타민이 듬뿍 들어있는 우거지를 이용한 구수한 찌개요리예요~', 30, '보통', 4, '찌개/전골/스튜', '한식', '124Kcal', '농림수산식품교육문화정보원', 3),
(76, 'r76', '샤브샤브', '부담없이 먹을 수 있는 샤브샤브, 점심메뉴로도 좋습니다~', 30, '보통', 4, '찌개/전골/스튜', '한식', '385Kcal', '농림수산식품교육문화정보원', 3),
(77, 'r77', '국수전골', '입맛 없을 때, 전골냄비에 끓여낸 보글보글 국수전골! 서늘한 날씨에 좋습니다~', 40, '보통', 4, '찌개/전골/스튜', '한식', '289Kcal', '농림수산식품교육문화정보원', 3),
(78, 'r78', '낙지전골', '갖가지 재료를 듬뿍 넣은 시원한 전골요리로 저녁 식탁을 꾸며보세요~', 40, '보통', 2, '찌개/전골/스튜', '한식', '236Kcal', '농림수산식품교육문화정보원', 3),
(79, 'r79', '선지국', '선지는 단백질이 풍부하고 철분이 많이 함유되 씹으면 고소한 맛과 영양이 그대로 전해진답니다.', 30, '보통', 4, '국', '한식', '190Kcal', '농림수산식품교육문화정보원', 3),
(80, 'r80', '콩나물국밥', '콩나물을 넣어 시원한 국밥 한뚝배기 하실래요~', 30, '초보환영', 4, '밥', '한식', '367Kcal', '농림수산식품교육문화정보원', 1),
(81, 'r81', '곰탕', '곰탕, 이제는 집에서 끓여 더욱 깊은 맛을 내보세요.', 120, '보통', 4, '국', '한식', '360Kcal', '농림수산식품교육문화정보원', 3),
(82, 'r82', '설렁탕', '쇠뼈를 푹 고아낸 뽀얀 국물 한 대접 먹으면 기운이 솟아납니다.', 90, '보통', 4, '국', '한식', '507Kcal', '농림수산식품교육문화정보원', 3),
(83, 'r83', '도가니탕', '몸이 허하다고 느껴질때 도가니탕 한그릇으로 기운 챙기세요.', 180, '어려움', 4, '국', '한식', '600Kcal', '농림수산식품교육문화정보원', 3),
(84, 'r84', '꼬리곰탕', '꼬리곰탕 한그릇이면 허했던 기력을 찾을 수 있죠.', 60, '어려움', 4, '국', '한식', '310Kcal', '농림수산식품교육문화정보원', 3),
(85, 'r85', '갈비탕', '갈비탕으로 속을 달래보세요. 든든해집니다!', 175, '어려움', 4, '국', '한식', '370Kcal', '농림수산식품교육문화정보원', 3),
(86, 'r86', '부추김치', '부추는 향도 좋고 맛도 달아, 김치로 담그면 맛있습니다.', 20, '보통', 4, '밑반찬/김치', '한식', '50Kcal', '농림수산식품교육문화정보원', 4),
(87, 'r87', '파김치', '파김치는 익으면 젖갈과 맛이 잘 어울려 든든한 밑반찬이 된답니다.', 30, '보통', 4, '밑반찬/김치', '한식', '40Kcal', '농림수산식품교육문화정보원', 4),
(88, 'r88', '백김치', '백김치를 담궈 시원한 김치를 맛보세요! 고춧가루를 넣은 김치와는 또다른 시원한 맛이랍니다.', 60, '보통', 4, '밑반찬/김치', '한식', '50Kcal', '농림수산식품교육문화정보원', 4),
(89, 'r89', '깻잎장아찌', '？잎장아찌는 만들기도 쉬우며, 입맛없을 때 먹기 좋은 밑반찬입니다.', 30, '보통', 4, '밑반찬/김치', '한식', '30Kcal', '농림수산식품교육문화정보원', 4),
(90, 'r90', '오이지장아찌무침', '아삭하게 씹히는 오이로 맛있는 오이장아찌 한번 만들어보세요.', 20, '보통', 4, '밑반찬/김치', '한식', '30Kcal', '농림수산식품교육문화정보원', 4),
(91, 'r91', '콩자반', '한 번 먹으면 고소한 맛과 톡톡터지는 씹는 맛이 입 안을 즐겁게 해준답니다.', 20, '보통', 4, '조림', '한식', '55Kcal', '농림수산식품교육문화정보원', 4),
(92, 'r92', '쇠고기장조림', '장조림 하나면 간단하게 식사 준비 할 수 있지요.', 30, '보통', 4, '조림', '한식', '146Kcal', '농림수산식품교육문화정보원', 4),
(93, 'r93', '연근조림', '연근이 아삭하게 씹혀요! 만들기도 아주 쉽지요~', 30, '보통', 4, '조림', '한식', '66Kcal', '농림수산식품교육문화정보원', 4),
(94, 'r94', '해물파전', '각종 해산물이 들어간 해물파전! 바다향과 고소한 향이 그대로~', 40, '보통', 4, '부침', '한식', '100Kcal', '농림수산식품교육문화정보원', 2),
(95, 'r95', '오이나물', '오이를 볶으면 아삭하면서도 고소한 맛이 나서 생채와는 또 다른 맛을 느낄수 있답니다.', 15, '초보환영', 4, '나물/생채/샐러드', '한식', '85Kcal', '농림수산식품교육문화정보원', 2),
(96, 'r96', '냉이된장찌개', '모시조개로 시원한 국물맛을 내고, 냉이로 향긋한 내음이 나는 냉이조갯국 만들어 보세요~', 30, '보통', 4, '찌개/전골/스튜', '한식', '109Kcal', '농림수산식품교육문화정보원', 3),
(97, 'r97', '계란말이', '도시락 반찬의 단골메뉴이자 훌륭한 안주인 계란말이입니다.', 30, '초보환영', 4, '부침', '한식', '110Kcal', '농림수산식품교육문화정보원', 2),
(98, 'r98', '닭강정', '양념치킨보다 달콤하고 바삭한 닭강정. 손이 절로 가지요.', 40, '보통', 2, '튀김/커틀릿', '한식', '110Kcal', '농림수산식품교육문화정보원', 2),
(99, 'r99', '배추겉절이', '간단하면서도 입맛을 돋우는 반찬으로는 배추 겉절이가 최고지요!', 30, '초보환영', 4, '밑반찬/김치', '한식', '55Kcal', '농림수산식품교육문화정보원', 4),
(100, 'r100', '더덕구이', '더덕을 양념해 구우면 향이 솔솔~ 입안이 즐거운 식사가 되지요.', 35, '보통', 4, '구이', '한식', '45Kcal', '농림수산식품교육문화정보원', 2),
(101, 'r101', '감자조림', '감자는 간장에 조리면 유난히 더 달고 맛있는것 같아요~~', 40, '초보환영', 4, '조림', '한식', '108Kcal', '농림수산식품교육문화정보원', 4),
(102, 'r102', '마른오징어조림', '마른 오징어를 맛있는 양념장에 버무리면 쫄깃함과 양념의 맛이 씹어도 씹어도 질리지 않아요~', 30, '초보환영', 4, '밑반찬/김치', '한식', '140Kcal', '농림수산식품교육문화정보원', 4),
(103, 'r103', '죽순볶음', '쇠고기와 죽순은 궁합이 잘 맞는 음식이지요. 향이 좋은 죽순을 볶아 드셔보세요.', 20, '보통', 4, '볶음', '한식', '70Kcal', '농림수산식품교육문화정보원', 2),
(104, 'r104', '호박전', '젊어서도 늙어서도 맛있는 호박! 애호박으로 고소한 전을 부쳐보아요~', 30, '초보환영', 4, '부침', '한식', '105Kcal', '농림수산식품교육문화정보원', 2),
(105, 'r105', '탕수육', '가장 보편적인 요리방법으로 만든 탕수육입니다..달콤 새콤한 소스에 찍어먹는 고기튀김의 맛은..정말 언제나 맛있죠~', 30, '보통', 2, '튀김/커틀릿', '중국', '616Kcal', '농림수산식품교육문화정보원', 2),
(106, 'r106', '콩국계란찜', '콩국물 베이스가 들어간 고소한 계란찜 한번 드셔보세요~ 영양도 듬뿍, 건강에도 OK!!', 30, '보통', 2, '찜', '퓨전', '80Kcal', '농림수산식품교육문화정보원', 3),
(107, 'r107', '불고기', '배에 재워 더 달콤하고 부드러운 불고기~ 오늘 저녁 어떠세요?', 20, '보통', 4, '볶음', '한식', '172Kcal', '농림수산식품교육문화정보원', 2),
(108, 'r108', '부추전', '피를 맑게 해준다는 부추! 부추를 밀가루 반죽과 함께 섞어 노릇하고 바삭하게 구워낸 전요리랍니다.', 30, '보통', 4, '부침', '한식', '151Kcal', '농림수산식품교육문화정보원', 2),
(109, 'r109', '돼지갈비구이', '돼지갈비를 양념에 잘 재워 채소에 싸 드셔보세요. 입안 가득 넣어도 계속 계속 들어갈거에요.', 50, '초보환영', 4, '구이', '한식', '1000Kcal', '농림수산식품교육문화정보원', 2),
(110, 'r110', '모듬초밥', '여러가지 해산물을 이용해 초밥을 만들어보세요. 입도 눈도 즐겁운 식사게 될거에요~', 50, '보통', 4, '밥', '일본', '200Kcal', '농림수산식품교육문화정보원', 1),
(111, 'r111', '꽁치무조림', '통조림으로 간단하고 맛있게 요리하는 법! 통조림은 무조건 맛없다는 고정관념을 깨드리는 요리가 있어요~', 25, '초보환영', 4, '조림', '한식', '185Kcal', '농림수산식품교육문화정보원', 4),
(112, 'r112', '김치적', '김치의 아삭함과 개운함을 산적에서 느끼는 새로움~ 산적의 맛이 새로워집니다', 25, '초보환영', 4, '부침', '한식', '350Kcal', '농림수산식품교육문화정보원', 2),
(113, 'r113', '낙지볶음', '톡 쏘는 매콤한 양념에 쫄깃한 낙지를 살짝만 볶아보세요~ 술안주로도, 밥반찬으로도, 이보다 좋은 것이 없답니다!', 30, '보통', 2, '볶음', '한식', '134Kcal', '농림수산식품교육문화정보원', 2),
(114, 'r114', '두부김치', '맛있게 익은 김치에 참기름, 깨소금 양념해서 따뜻한 두부와 함께 먹으면 담백하고 시원한 맛이 일품이죠.', 20, '초보환영', 4, '볶음', '한식', '253Kcal', '농림수산식품교육문화정보원', 2),
(115, 'r115', '오믈렛', '이쁜 오믈렛속에 숨겨진 밥을 떠먹는 재미! 한번 느껴보세요', 20, '초보환영', 2, '양식', '서양', '311Kcal', '농림수산식품교육문화정보원', 2),
(116, 'r116', '롤케비지(양배추말이)', '고기로 속을 만들어 양배추로 돌돌 말아 찌면 양배추의 색다른 변신에 놀라실거에요.', 60, '보통', 2, '찜', '서양', '235Kcal', '농림수산식품교육문화정보원', 3),
(117, 'r117', '두부미역냉채', '두부의 고소함과 미역의 씹는 맛이 어우러져 상큼 개운한 냉채~~!! 다이어트식으로 그만이지요!!', 30, '초보환영', 2, '나물/생채/샐러드', '한식', '95Kcal', '농림수산식품교육문화정보원', 2),
(118, 'r118', '중국식볶음밥', '중국요리는 센불이 가장 중요해요. 팬을 뜨겁게 달궈서 재빨리 볶아 주세요.', 30, '보통', 4, '밥', '중국', '528Kcal', '농림수산식품교육문화정보원', 1),
(119, 'r119', '해장라면', '라면에 여러가지 야채를 넣어 만든 시원하고 푸짐한 메뉴입니다. 술 마신 다음날 스피드하게 먹으면 너무 좋아요~', 30, '초보환영', 4, '만두/면류', '한식', '290Kcal', '농림수산식품교육문화정보원', 1),
(120, 'r120', '국수계란말이', '국수를 계란에 담아 색다름을 더해보세요~', 30, '보통', 2, '만두/면류', '일본', '260Kcal', '농림수산식품교육문화정보원', 1),
(121, 'r121', '꽁치간장구이', '꽁치는 구이나 조림으로만 생각하셨죠? 간장양념을 발라가며 정성스럽게 구워보세요. 정말 맛있답니다~', 40, '초보환영', 4, '구이', '한식', '110Kcal', '농림수산식품교육문화정보원', 2),
(122, 'r122', '감자고추채볶음', '감자를 채썰어 노랗게 볶은다음 색깔이 이쁜 홍고추등을 넣어 볶아주면 아주 예쁘고 맛있는 볶음요리가 되지요~', 30, '초보환영', 2, '볶음', '한식', '189Kcal', '농림수산식품교육문화정보원', 2),
(123, 'r123', '가는파잡채', '가는파로 잡채 요리한번 해볼까요?', 30, '초보환영', 2, '볶음', '한식', '175Kcal', '농림수산식품교육문화정보원', 2),
(124, 'r124', '묵과양념장', '담백한 도토리묵을 새콤한 양념장과 버무리면 그맛이 환상~ 많이 먹어도 살찌지 않아요!', 20, '초보환영', 2, '나물/생채/샐러드', '한식', '112Kcal', '농림수산식품교육문화정보원', 2),
(125, 'r125', '고등어살튀김과소스', '고등어를 녹말가루에 묻혀 바삭하게 튀겨 맛있는 소스와 곁들이면 정말 놀라운 맛이납니다.', 30, '보통', 2, '튀김/커틀릿', '한식', '390Kcal', '농림수산식품교육문화정보원', 2),
(126, 'r126', '가지와마른새우무침', '가지와 새우를 같이 볶은다음, 맛있는 양념을 하여 만들었지요. 도시락 반찬에 안성맞춤이랍니다.', 30, '초보환영', 2, '볶음', '한식', '102Kcal', '농림수산식품교육문화정보원', 2),
(127, 'r127', '채소말이샤브샤브', '담백하고 깊은 맛이나는 육수에 고기와 야채를 돌돌말아 살짝 익혀먹으면 입맛이 저절로 살아나요~', 60, '보통', 2, '찌개/전골/스튜', '일본', '280Kcal', '농림수산식품교육문화정보원', 3),
(128, 'r128', '떡갈비구이', '갈비 속에 떡이 들어있듯이 쫄깃쫄깃해서~ 떡갈비!', 50, '보통', 2, '구이', '한식', '380Kcal', '농림수산식품교육문화정보원', 2),
(129, 'r129', '골뱅이무침', '간단하게 술상을 차릴때 새콤달콤한 골뱅이무침 하나면 OK!', 30, '초보환영', 2, '나물/생채/샐러드', '한식', '226Kcal', '농림수산식품교육문화정보원', 2),
(130, 'r130', '두부양념조림', '영양가 풍부한 두부에 간장소스를 곁들이세요. 두부요리는 남녀노소 좋아하는 메뉴입니다.', 20, '초보환영', 2, '조림', '한식', '98Kcal', '농림수산식품교육문화정보원', 4),
(131, 'r131', '육회', '싱싱한 육회는 회 못지않게 맛이 좋습니다.', 30, '초보환영', 2, '나물/생채/샐러드', '한식', '120Kcal', '농림수산식품교육문화정보원', 2),
(132, 'r132', '까르보나라스파게티', '깊고 진한 크림소스의 까르보나라 스파게티! 느끼하지 않고 부드럽습니다.', 40, '보통', 2, '만두/면류', '이탈리아', '550Kcal', '농림수산식품교육문화정보원', 1),
(133, 'r133', '삼계탕', '여름철 보양식의 대표음식 삼계탕! 시원한 국물과 쫄깃한 닭고기로 몸보신하세요~', 60, '보통', 2, '국', '한식', '565Kcal', '농림수산식품교육문화정보원', 3),
(134, 'r134', '주먹밥', '피크닉에 빠져서는 안될 단골메뉴! 주먹밥으로 가족들과 가벼운 피크닉을 즐겨보세요.', 30, '초보환영', 2, '도시락/간식', '한식', '350Kcal', '농림수산식품교육문화정보원', 1),
(135, 'r135', '유부계란찜', '유부에 넣어 달걀찜을 하면 도시락 반찬으로 모양도 예쁘고 맛도 있는 센스만점 반찬이 된답니다~', 20, '보통', 2, '찜', '한식', '105Kcal', '농림수산식품교육문화정보원', 3),
(136, 'r136', '속채운감자', '찐 감자에 여러가지 재료를 넣어 속을 꽉 채운요리랍니다.', 20, '초보환영', 2, '구이', '서양', '200Kcal', '농림수산식품교육문화정보원', 2),
(137, 'r137', '떡갈비샌드위치', '인스턴트 샌드위치는 비만의 원인이랍니다. 직접 만들어 맛과 영양이 우수한 샌드위치로 건강을 챙기세요.', 30, '보통', 2, '샌드위치/햄버거', '퓨전', '380Kcal', '농림수산식품교육문화정보원', 1),
(138, 'r138', '버섯덮밥', '향긋한 버섯으로 만드는 간단하고 폼나는 요리! 간장소스가 맛을 더해준답니다~', 40, '초보환영', 4, '밥', '한식', '480Kcal', '농림수산식품교육문화정보원', 1),
(139, 'r139', '닭고기수삼샐러드', '영양가 풍부한 닭고기와 수삼으로 고급스러운 샐러드를 만들어보세요. 즐거운 식사가 된답니다.', 60, '보통', 2, '나물/생채/샐러드', '한식', '300Kcal', '농림수산식품교육문화정보원', 2),
(140, 'r140', '컬리플라워해물샐러드', '컬리플라워를 준비하고, 여러가지 해물도 준비해놓습니다. 머스터드 드레싱과 멋진 조화를 이룹니다.', 30, '보통', 2, '나물/생채/샐러드', '서양', '135Kcal', '농림수산식품교육문화정보원', 2),
(141, 'r141', '과일샐러드', '향긋한 과일향이 너무 좋아요. 만들기도 참 쉽습니다.', 20, '초보환영', 2, '나물/생채/샐러드', '서양', '171Kcal', '농림수산식품교육문화정보원', 2),
(142, 'r142', '연어샐러드', '훈제연어에 양파와 케이퍼 얹어 드셔보세요. 짭짤하고 훈연한 향이 입맛을 자꾸 자극한답니다~', 10, '초보환영', 2, '나물/생채/샐러드', '서양', '135Kcal', '농림수산식품교육문화정보원', 2),
(143, 'r143', '시금치샐러드', '상큼한 시금치에 담백한 베이컨과 양송이와 가루치즈, 그리고 레몬드레싱.. 상큼함이 전해져요.', 20, '초보환영', 2, '나물/생채/샐러드', '서양', '290Kcal', '농림수산식품교육문화정보원', 2),
(144, 'r144', '채소수프', '다양한 야채로 만든 영양만점 수프랍니다~', 40, '초보환영', 2, '밥', '서양', '170Kcal', '농림수산식품교육문화정보원', 1),
(145, 'r145', '부대찌개', '햄과 갖은 재료로 푸짐한 부대찌개로 오늘 저녁상을 근사하게 차려보세요~', 40, '초보환영', 2, '찌개/전골/스튜', '한식', '125Kcal', '농림수산식품교육문화정보원', 3),
