(200, 'r200', '고추장아찌', '맵지 않은 청고추로 맛나는 장아찌 한 번 담가볼까요', 30, '보통', 2, '밑반찬/김치', '한식', '70Kcal', '농림수산식품교육문화정보원', 4);

INSERT INTO recipe (id, code, title, description, cook_time_min, difficulty, servings, category, cuisine, kcal, source, storage_days) VALUES
(201, 'r201', '김치어묵', '집에서 만드는 어묵요리. 김치를 넣어서 느끼하지 않고 담백하게 만들 수 있어요.', 40, '보통', 2, '튀김/커틀릿', '퓨전', '519Kcal', '농림수산식품교육문화정보원', 2),
(202, 'r202', '쇠고기무국', '쇠고기무국에 제일 중요한것은 바로 무의 선택이죠', 40, '보통', 2, '국', '한식', '98Kcal', '농림수산식품교육문화정보원', 3),
(203, 'r203', '명란젓찌개', '명란은 익으면 표피가 줄어들고 단단해지므로 반드시 칼집을 넣어 사용하세요.', 30, '보통', 2, '찌개/전골/스튜', '한식', '313Kcal', '농림수산식품교육문화정보원', 3),
(204, 'r204', '육개장', '육개장에는 얼큰한 국물맛을 내는것이 제일 중요해요.', 60, '어려움', 2, '국', '한식', '180Kcal', '농림수산식품교육문화정보원', 3),
(205, 'r205', '고추장스파게티', '크림이 아닌 고추장 스파게티! 생소하시죠? 일단 한 번 드셔보세요~', 30, '보통', 2, '만두/면류', '퓨전', '380Kcal', '농림수산식품교육문화정보원', 1),
(206, 'r206', '해물전골', '풍성한 해물로 식탁을 차려보세요.', 30, '보통', 2, '찌개/전골/스튜', '한식', '285Kcal', '농림수산식품교육문화정보원', 3),
(207, 'r207', '양상추튀김', '비타민 풍부한 양상추 속에 갖가지 야채를 넣어서 튀겨보세요. 영양가 풍부한 맛있는 요리가 탄생합니다.', 40, '보통', 2, '튀김/커틀릿', '퓨전', '421Kcal', '농림수산식품교육문화정보원', 2),
(208, 'r208', '초교탕', '부드럽게 깊은 맛을 내는 초교탕. 영양가 많은 초교탕으로 더운여름 이열치열식으로 몸챙기세요!', 60, '보통', 2, '국', '한식', '398Kcal', '농림수산식품교육문화정보원', 3),
(209, 'r209', '삼겹살깻잎전', '돼지고기의 누린 내가 싫으시다구요? 걱정마세요! 향긋한 깻잎에 싸서 전을 부치면 매우 향긋하답니다~', 30, '보통', 2, '부침', '한식', '200Kcal', '농림수산식품교육문화정보원', 2),
(210, 'r210', '우유두부', '우유로 두부를 만들 수 있다구요?', 40, '보통', 2, '도시락/간식', '퓨전', '120Kcal', '농림수산식품교육문화정보원', 1),
(211, 'r211', '닭꼬치구이', '닭꼬치구이!! 술안주에 그만이죠^^', 40, '보통', 2, '구이', '한식', '370Kcal', '농림수산식품교육문화정보원', 2),
(212, 'r212', '녹차수제비', '녹차를 넣으면 향이 더욱 좋답니다.', 60, '보통', 2, '만두/면류', '한식', '360Kcal', '농림수산식품교육문화정보원', 1),
(213, 'r213', '삼겹살치즈구이', '어른들이 좋아하는 메뉴 삼겹살! 치즈를 얹어 아이들도 함께 즐겨보아요~', 40, '보통', 2, '구이', '퓨전', '450Kcal', '농림수산식품교육문화정보원', 2),
(214, 'r214', '갈비떡볶이', '갈비와 떡으로 만든 떡볶이!! 정말 맛있어요^^', 40, '어려움', 2, '도시락/간식', '한식', '380Kcal', '농림수산식품교육문화정보원', 1),
(215, 'r215', '오징어산적', '오징어로 산적 요리 해볼까요?', 30, '보통', 2, '구이', '한식', '190Kcal', '농림수산식품교육문화정보원', 2),
(216, 'r216', '두부오믈렛', '계란과 부드러운 두부로 맛있는 오믈렛 만들어보세요~ 간편하면서도 근사한 요리가 된답니다!', 30, '보통', 2, '볶음', '서양', '160Kcal', '농림수산식품교육문화정보원', 2),
(217, 'r217', '잼(사과, 딸기, 포도)', '여러가지 잼이 있으면 빵을 더 맛있게 먹을 수 있어요!', 30, '어려움', 2, '양념장', '서양', '36Kcal', '농림수산식품교육문화정보원', 7),
(218, 'r218', '사골탕', '영양가 풍부한 사골로 국물을 내세요.', 60, '보통', 2, '국', '한식', '400Kcal', '농림수산식품교육문화정보원', 3),
(219, 'r219', '감자국수', '감자로 국수를 만들수 있어요. 약간 번거롭기는 하지만 감자로 만든 국수가 어찌나 쫄깃쫄깃한지 별미로 한 번 만들어 드셔보세요!', 40, '보통', 2, '만두/면류', '한식', '320Kcal', '농림수산식품교육문화정보원', 1),
(220, 'r220', '김치수제비', '따끈따근한 국물에 쫄깃한 수제비~ 한번 만들어보세요', 40, '초보환영', 2, '만두/면류', '한식', '410Kcal', '농림수산식품교육문화정보원', 1),
(221, 'r221', '오곡밥쌈밥정식', '구수한 쌈장에 영양가 풍부한 오곡밥을 곁들여 고향을 맛을 느껴보세요.', 40, '초보환영', 2, '밥', '한식', '350Kcal', '농림수산식품교육문화정보원', 1),
(222, 'r222', '오징어숙회', '오징어을 익혀서 초고추장에 찍어드세요.', 40, '초보환영', 2, '나물/생채/샐러드', '한식', '150Kcal', '농림수산식품교육문화정보원', 2),
(223, 'r223', '짬뽕해물탕밥', '얼큰하게 고춧가루를 넣어 영양가 풍부한 해물을 넣어 맛있게 만들어보세요.', 40, '보통', 2, '밥', '중국', '540Kcal', '농림수산식품교육문화정보원', 1),
(224, 'r224', '제육배추찜', '배추에 갈은 돼지고기를 넣어 모양있게 돌돌 말았답니다~ 고기 육수로 맛나게 국물을 내어 찜요리를 해보세요!', 30, '초보환영', 2, '찜', '서양', '308Kcal', '농림수산식품교육문화정보원', 3),
(225, 'r225', '코다리찜', '코다리찜, 밑반찬으로 그만이죠!', 40, '보통', 4, '찜', '한식', '156Kcal', '농림수산식품교육문화정보원', 3),
(226, 'r226', '생선초밥', '싱싱한 생선을 새콤달콤 양념한 밥위에 올려 먹으면 훌륭한 일식 초밥이 되는거지요~ 정말 신선합니다!', 60, '어려움', 4, '밥', '일본', '1250Kcal', '농림수산식품교육문화정보원', 1),
(227, 'r227', '버섯만두전골', '푸짐한 버섯만두 전골로 오늘 저녁 어떠세요?', 60, '보통', 4, '만두/면류', '한식', '540Kcal', '농림수산식품교육문화정보원', 1),
(228, 'r228', '해물밥전', '해물을 전으로 부쳐 먹어보아요~', 30, '보통', 4, '밥', '한식', '320Kcal', '농림수산식품교육문화정보원', 1),
(229, 'r229', '두부스테이크', '몸에 좋은 두부로 스테이크를 만들어보세요~', 40, '초보환영', 2, '부침', '퓨전', '188Kcal', '농림수산식품교육문화정보원', 2),
(230, 'r230', '두부카나페', '한입에 쏘옥 먹을 수있는 까나페를 두부로 만들어보세요. 두부의 부드러운 맛이 입안에서 살살녹는답니다.', 30, '초보환영', 4, '도시락/간식', '퓨전', '265Kcal', '농림수산식품교육문화정보원', 1),
(231, 'r231', '홍차계란장조림', '계란 장조림에 홍차를 넣으면 향과 맛이 아주 깊어져요!', 40, '초보환영', 4, '밑반찬/김치', '한식', '130Kcal', '농림수산식품교육문화정보원', 4),
(232, 'r232', '가지된장찜', '구수한 된장 양념에 가지를 조려보세요~', 30, '초보환영', 2, '찜', '한식', '230Kcal', '농림수산식품교육문화정보원', 3),
(233, 'r233', '닭고기카레튀김', '닭고기와 카레의 환상조합!', 40, '보통', 2, '튀김/커틀릿', '퓨전', '310Kcal', '농림수산식품교육문화정보원', 2),
(234, 'r234', '고춧기름', '고추기름을 만들때는 불조절을 잘 해야 해요!', 30, '초보환영', 4, '양념장', '중국', '134Kcal', '농림수산식품교육문화정보원', 7),
(235, 'r235', '생태매운탕', '얼큰하고 시원한 생태매운탕! 시원한 국물맛에 보들보들한 생태살이 입에서 살살 녹아요.', 40, '초보환영', 2, '국', '한식', '224Kcal', '농림수산식품교육문화정보원', 3),
(236, 'r236', '두부굴찌개', '두부와 시원한 맛을 내는 굴을 같이 넣어보세요~ 시원함이 배가됩니다!', 30, '보통', 4, '찌개/전골/스튜', '한식', '135Kcal', '농림수산식품교육문화정보원', 3),
(237, 'r237', '버섯두부찌개', '몸에 좋은 버섯과 두부가 들어간 얼큰한 찌개로 오늘 저녁밥상 차려보세요~ 남편이 좋아해요!', 40, '초보환영', 2, '찌개/전골/스튜', '한식', '170Kcal', '농림수산식품교육문화정보원', 3),
(238, 'r238', '김치주먹밥', '김치로 느끼함을 제거한 주먹밥을 즐겨보세요~', 40, '보통', 4, '밥', '한식', '380Kcal', '농림수산식품교육문화정보원', 1),
(239, 'r239', '홍합탕', '싱싱한 홍합으로 끓인 홍합탕! 정말 시원해요~', 40, '보통', 4, '국', '한식', '75Kcal', '농림수산식품교육문화정보원', 3),
(240, 'r240', '돼지갈비찜', '잔칫상에 빠질 수 없는 갈비찜! 이번에는 돼지갈비를 매콤하게 즐겨보세요~', 60, '보통', 4, '찜', '한식', '220Kcal', '농림수산식품교육문화정보원', 3),
(241, 'r241', '떡볶이', '한국의 대표분식 떡볶이! 남녀노소 좋아해요~', 30, '보통', 4, '도시락/간식', '한식', '225Kcal', '농림수산식품교육문화정보원', 1),
(242, 'r242', '제육불고기', '밥반찬에, 술안주에 너무 좋은 메뉴랍니다~', 50, '보통', 4, '구이', '한식', '210Kcal', '농림수산식품교육문화정보원', 2),
(243, 'r243', '배추밤김치', '잘 절인 배추속에 양념장 솔솔 버무린 밤을 넣어서 만든 고급 김치입니다.', 60, '보통', 4, '밑반찬/김치', '한식', '75Kcal', '농림수산식품교육문화정보원', 4),
(244, 'r244', '보쌈김치', '김장 때면 빠질 수 없는 보쌈김치!', 180, '어려움', 4, '밑반찬/김치', '한식', '68Kcal', '농림수산식품교육문화정보원', 4),
(245, 'r245', '사골우거지탕', '고향의 어머니 손맛을 느낄 수 있어요. 잘 우려낸 사골국물에 고소한 우거지까지! 바로 이맛이야~', 60, '보통', 4, '국', '한식', '156Kcal', '농림수산식품교육문화정보원', 3),
(246, 'r246', '찬밥전', '찬밥이 남았다구요? 참치와 갖은 채소를 다져서 전으로 만들어 보세요! 아이들이 좋아해요~', 20, '초보환영', 4, '부침', '한식', '146Kcal', '농림수산식품교육문화정보원', 2),
(247, 'r247', '단팥죽', '팥을 부드럽게 삶아 으깨서 만든 달달한 단팥죽! 간식으로 좋아요~', 50, '초보환영', 2, '밥', '한식', '166Kcal', '농림수산식품교육문화정보원', 1),
(248, 'r248', '불고기낙지전골', '얼큰한 국물속에 쫄깃한 낙지와 담백한 불고기가 어우러져 있는 전골요리 어떠세요?', 40, '보통', 2, '찌개/전골/스튜', '한식', '247Kcal', '농림수산식품교육문화정보원', 3),
(249, 'r249', '잔멸치된장볶음', '오늘도 반찬이 고민되시나요? 멸치를 볶아 놓으면 며칠 동안은 밑반찬 걱정 없이 지낼 수 있어요..', 30, '초보환영', 4, '밑반찬/김치', '한식', '75Kcal', '농림수산식품교육문화정보원', 4),
(250, 'r250', '별미밥', '이름도 별난 별미밥으로 별식을 즐겨보세요~', 40, '보통', 4, '밥', '한식', '325Kcal', '농림수산식품교육문화정보원', 1),
(251, 'r251', '김치피자', '김치는 싫어하지만 피자는 좋아하는 우리 아이들을 위해 색다른 퓨전 요리를 준비해 봤어요.', 30, '보통', 4, '피자', '퓨전', '230Kcal', '농림수산식품교육문화정보원', 2),
(252, 'r252', '채소비빔소면', '채소랑 소면이랑 만났어요.  새콤달콤한 고추장에 비벼서 맛있게 드세요~', 30, '보통', 2, '만두/면류', '한식', '414Kcal', '농림수산식품교육문화정보원', 1),
(253, 'r253', '오징어탕수', '탕수육의 변화된 맛을 원한다면 영양가 만점인 오징어를 반죽해서 탕수육 소스에 버무리면 되지요~', 40, '보통', 4, '튀김/커틀릿', '중국', '420Kcal', '농림수산식품교육문화정보원', 2),
(254, 'r254', '콩나물버섯덮밥', '향긋한 버섯향과 아삭한 콩나물이 들어간 덮밥을 양념장으로 슥슥 비벼 드셔보세요~ 입맛이 확! 살아 난답니다.', 40, '보통', 2, '밥', '한식', '232Kcal', '농림수산식품교육문화정보원', 1),
(255, 'r255', '어묵꼬치', '겨울철과 가장 잘 어우리는 음식이랍니다. 따뜻한 국물에 시원한 맛이 정말 끝내줍니다~', 40, '보통', 2, '국', '한식', '197Kcal', '농림수산식품교육문화정보원', 3),
(256, 'r256', '닭다리굴소스볶음', '부드러운 닭다리의 살을 바라 굴소스에 볶아보세요~ 굴소스의 진한 맛이 정말 색다르답니다.', 30, '보통', 4, '볶음', '중국', '203Kcal', '농림수산식품교육문화정보원', 2),
(257, 'r257', '영양채소밥', '영양이 듬뿍! 한끼 식사로 아주 아주 든든하지요.', 40, '보통', 2, '밥', '한식', '375Kcal', '농림수산식품교육문화정보원', 1),
(258, 'r258', '사색나물', '나물종류를 쉽게 만들어보세요. 반찬이 없을때 준비해둔 나물로 비빔밥을 해서 드셔보세요.', 30, '초보환영', 2, '나물/생채/샐러드', '한식', '55Kcal', '농림수산식품교육문화정보원', 2),
(259, 'r259', '떡잡채', '떡으로 만든 잡채의 맛. 아이들 간식으로 좋겠죠?', 20, '보통', 4, '볶음', '한식', '265Kcal', '농림수산식품교육문화정보원', 2),
(260, 'r260', '두부채소냉채', '영양가 풍부한 두부로 만든 냉채를 집에서 손쉽게 준비해보세요. 고소한 땅콩소스를 곁들여 준비하세요.', 30, '초보환영', 2, '나물/생채/샐러드', '한식', '256Kcal', '농림수산식품교육문화정보원', 2),
(261, 'r261', '약과', '달달하게 입맛 당기는 약과..오늘 한번 도전해보세요~', 40, '보통', 2, '떡/한과', '한식', '135Kcal', '농림수산식품교육문화정보원', 2),
(262, 'r262', '참치주먹밥', '참치 주먹밥 싸서 소풍을 떠나보아요~^^', 30, '보통', 4, '도시락/간식', '한식', '404Kcal', '농림수산식품교육문화정보원', 1),
(263, 'r263', '유부미역된장국', '일본식된장국에 유부와 미역을 넣어서 색다른 맛을 느껴보세요~', 30, '초보환영', 4, '국', '한식', '130Kcal', '농림수산식품교육문화정보원', 3),
(264, 'r264', '삼색수제비', '야채즙으로 반죽해서 잼있게 만들어 보세요.. 먹는 즐거움, 보는 즐거움.. 아이들이 잘 안먹는 야채를 이용한 수제비입니다.', 30, '보통', 4, '만두/면류', '한식', '392Kcal', '농림수산식품교육문화정보원', 1),
(265, 'r265', '고들빼기김치', '고들빼기의 향이 아주 일품인 고들빼기 김치!', 70, '어려움', 2, '밑반찬/김치', '한식', '56Kcal', '농림수산식품교육문화정보원', 4),
(266, 'r266', '달래굴파전', '향긋한 달래와 싱싱한 굴을 넣은 아주 맛있는 파전을 만들어보세요.', 30, '초보환영', 2, '부침', '한식', '189Kcal', '농림수산식품교육문화정보원', 2),
(267, 'r267', '달래장김치', '입맛 없을 때 달래로 만든 김치하나면 반찬 걱정이 없어요.', 30, '보통', 4, '밑반찬/김치', '한식', '65Kcal', '농림수산식품교육문화정보원', 4),
(268, 'r268', '두릅된장무침', '구수한 된장에 두릅을 오물조물 무쳐보세요. 정말 구수하답니다!', 30, '초보환영', 2, '나물/생채/샐러드', '한식', '75Kcal', '농림수산식품교육문화정보원', 2),
(269, 'r269', '숙주미나리무침', '향긋한 미나리와 숙주를 함께 무쳐보세요. 정말 입맛이 새록새록 살아납니다.', 20, '초보환영', 2, '나물/생채/샐러드', '한식', '75Kcal', '농림수산식품교육문화정보원', 2),
(270, 'r270', '참나물고추장무침', '우리 입맛에 맞는 고추장 소스에 아삭한 참나물을 무쳐보세요. 밥 반찬으로 너무 좋아요.', 20, '초보환영', 2, '나물/생채/샐러드', '한식', '55Kcal', '농림수산식품교육문화정보원', 2),
(271, 'r271', '오징어통구이', '오징어에 칼집을 촘촘히 넣어 만들었답니다. 매콤한 고추장 소스를 만들어 쓰윽 발라가며 맛있게 구워보세요.', 30, '초보환영', 2, '구이', '한식', '180Kcal', '농림수산식품교육문화정보원', 2),
(272, 'r272', '닭고기콩나물덮밥', '콩나물만 넣으면 심심하니까! 고소한 닭가슴살을 곁들여 고추장에 비벼비벼~', 40, '보통', 4, '밥', '한식', '400Kcal', '농림수산식품교육문화정보원', 1),
(273, 'r273', '김치두부쌈', '납작한 돼지고기위에 두부를 얹고 그위에 신김치를 얹어서 먹어보세요. 배가 든든해 져요.', 40, '보통', 4, '찜', '한식', '250Kcal', '농림수산식품교육문화정보원', 3),
(274, 'r274', '호박두부찌개', '추운 날씨에 호박두부 찌개를 보글보글 맛있게 끓여보세요!', 30, '초보환영', 4, '찌개/전골/스튜', '한식', '115Kcal', '농림수산식품교육문화정보원', 3),
(275, 'r275', '해파리해물냉채', '싱싱한 해파리와 새우 등의 해물을 겨자 소스에 맛있게 무쳐보세요.', 40, '초보환영', 2, '나물/생채/샐러드', '한식', '112Kcal', '농림수산식품교육문화정보원', 2),
(276, 'r276', '치킨롤', '담백한 닭살에 아삭한 채소를 넣어 김밥모양처럼 돌돌 말아 보세요~한입에 쏙!', 40, '보통', 4, '구이', '서양', '280Kcal', '농림수산식품교육문화정보원', 2),
(277, 'r277', '아스파라거스새우볶음', '갖가지 야채를 넣어서 기름에 살짝 볶은 향이 진하고 맛이 부드러운 요리랍니다.', 30, '보통', 4, '볶음', '서양', '150Kcal', '농림수산식품교육문화정보원', 2),
(278, 'r278', '꽃만두국(완당국)', '예쁘게 만두를 빗어 보세요.. 만두소는 부드로게 만드시구요..', 40, '보통', 4, '만두/면류', '중국', '477Kcal', '농림수산식품교육문화정보원', 1),
(279, 'r279', '돼지고기표고볶음', '표고버섯의 향이 은은하게 퍼지는 맛있는 볶음요리를 해보세요!', 30, '초보환영', 2, '볶음', '중국', '221Kcal', '농림수산식품교육문화정보원', 2),
(280, 'r280', '오징어풋마늘산적', '오징어의 색다른 변신! 한번 맛 보면 그 맛을 잊을수 없답니다.', 30, '보통', 4, '부침', '한식', '160Kcal', '농림수산식품교육문화정보원', 2),
(281, 'r281', '상추겉절이비빔밥', '상추 겉절이를 손쉽게 만들어 밥에 넣어 비벼드세요. 입맛이 새록새록!', 30, '보통', 4, '밥', '한식', '395Kcal', '농림수산식품교육문화정보원', 1),
(282, 'r282', '두부알찜', '부드러운 두부에 여러가지 재료를 다양하게 넣어 맛있게 찜요리를 해보세요.', 30, '보통', 4, '찜', '한식', '134Kcal', '농림수산식품교육문화정보원', 3),
(283, 'r283', '연어양상추쌈', '붉은 연어를 양상추에 싸서 멋드러지게 요리해보세요. 정말 훌륭한 술안주이지요.', 20, '보통', 4, '나물/생채/샐러드', '서양', '135Kcal', '농림수산식품교육문화정보원', 2),
(284, 'r284', '브로콜리크림수프', '몸에 좋은 브로콜리를 부드러운 수프로 즐겨보세요~', 30, '어려움', 4, '밥', '서양', '164Kcal', '농림수산식품교육문화정보원', 1),
(285, 'r285', '해물떡꼬치', '싱싱한 해물을 떡이랑 같이 꼬치에 끼워 요리했답니다. 보기만 해도 침이 꿀꺽!', 30, '보통', 4, '구이', '퓨전', '168Kcal', '농림수산식품교육문화정보원', 2),
(286, 'r286', '옥수수볶음밥', '간단하게 먹을수 있는 볶음밥이예요. 여러가지 채소를 첨가해 보세요.', 20, '보통', 4, '밥', '퓨전', '375Kcal', '농림수산식품교육문화정보원', 1),
(287, 'r287', '김치꽁치조림', '통조림과 신김치만 있으면 금방 만들수 있어서 아주 편리하죠.', 20, '보통', 4, '찌개/전골/스튜', '한식', '165Kcal', '농림수산식품교육문화정보원', 3),
(288, 'r288', '치즈돈까스', '바삭하게 튀긴 돈까스에 쫀득한 치즈 맛이 더했답니다.', 40, '보통', 1, '튀김/커틀릿', '서양', '590Kcal', '농림수산식품교육문화정보원', 2),
(289, 'r289', '간장떡볶이', '고추장이 아닌 간장으로 맛을 낸 궁중식 떡볶이! 맵지 않아 아이들도 잘 먹어요~', 60, '보통', 4, '볶음', '한식', '179Kcal', '농림수산식품교육문화정보원', 2),
(290, 'r290', '한국식타코샐러드', '춘권피에 맛있는 샐러드를 듬뿍 담았습니다. 한입 크기에 딱 어울리는 안주랍니다.', 30, '보통', 4, '나물/생채/샐러드', '퓨전', '290Kcal', '농림수산식품교육문화정보원', 2),
(291, 'r291', '김치쌈밥', '신김치만 남았을 때! 김치쌈밥으로 해결하세요~', 20, '보통', 2, '밥', '한식', '340Kcal', '농림수산식품교육문화정보원', 1),
(292, 'r292', '잔치국수', '출출할때 간식거리로 야참으로도 부담스럽지 않아요.', 30, '초보환영', 4, '만두/면류', '한식', '315Kcal', '농림수산식품교육문화정보원', 1),
(293, 'r293', '감자그라탕', '치즈의 고소함과 감자의 부드러움이 어우러진 아주 맛있는 요리랍니다.', 40, '보통', 4, '그라탕/리조또', '이탈리아', '237Kcal', '농림수산식품교육문화정보원', 2),
(294, 'r294', '코다리조림', '코다리를 맛있게 조려보세요. 밑반찬 뿐만 아니라 아주 좋은 술안주도 될수 있지요~', 30, '초보환영', 2, '조림', '한식', '175Kcal', '농림수산식품교육문화정보원', 4),
(295, 'r295', '치킨데리야끼', '맛있게 볶아만든 밥에 데리야끼 소스를 맛있게 한접시 먹음직스럽게 담아보세요.', 30, '보통', 2, '볶음', '일본', '580Kcal', '농림수산식품교육문화정보원', 2),
(296, 'r296', '순대볶음', '군것질로 가장 많이 선호하는 순대를 집에서 볶아 드셔 보세요.', 20, '초보환영', 4, '볶음', '한식', '210Kcal', '농림수산식품교육문화정보원', 2),
(297, 'r297', '닭갈비', '춘천닭갈비를 그대로 옮겨 놓은듯한 양념의 비법이 여기에 있지요. 춘천닭갈비를 그대로 옮겨 놓은듯한 맛!', 25, '보통', 2, '볶음', '한식', '189Kcal', '농림수산식품교육문화정보원', 2),
(298, 'r298', '베이컨꼬치구이', '베이컨에 여러가지 재료를 넣어 꼬치구이를 했답니다.', 20, '보통', 3, '구이', '퓨전', '350Kcal', '농림수산식품교육문화정보원', 2),
(299, 'r299', '열무비빔밥', '잘 익은 열무김치에 고추장 양념으로 더이상 말이 필요없죠?', 20, '보통', 2, '밥', '한식', '375Kcal', '농림수산식품교육문화정보원', 1),
(300, 'r300', '다시마볶음', '다시마를 볶아 다이어트식으로 즐겨보세요.', 20, '초보환영', 4, '볶음', '한식', '125Kcal', '농림수산식품교육문화정보원', 2),
(301, 'r301', '버섯잡채밥', '잡채에 가지런히 채썬 버섯을 넣어 맛있게 오물조물 무쳐서 밥위에 끼얹으면?', 40, '초보환영', 2, '밥', '중국', '520Kcal', '농림수산식품교육문화정보원', 1),
(302, 'r302', '쑥브리오슈', '막대모양이 조금 찌그러 져도 멋진 쑥브리오슈.', 60, '초보환영', 4, '빵/과자', '서양', '345Kcal', '농림수산식품교육문화정보원', 3),
(303, 'r303', '된장깻잎장아찌', '깻잎 장아찌 하나면 밥 한그릇 순식 간에 뚝딱!!', 20, '초보환영', 4, '밑반찬/김치', '한식', '80Kcal', '농림수산식품교육문화정보원', 4),
(304, 'r304', '비빔쌀국수', '쌀국수를 맛있게 월남식으로 비벼보세요. 흔히 먹는 비빔국수의 맛에 특별함을 더한 요리이지요.', 30, '초보환영', 4, '만두/면류', '한식', '275Kcal', '농림수산식품교육문화정보원', 1),
(305, 'r305', '아욱국', '시원한 아욱으로 국을 끓여 오늘 저녁식사로 어떠세요?', 30, '초보환영', 2, '국', '한식', '110Kcal', '농림수산식품교육문화정보원', 3),
(306, 'r306', '라볶이', '라면의 색다른 변신을 원하신다면 지금 한번 도전해 보세요.', 30, '초보환영', 2, '볶음', '한식', '390Kcal', '농림수산식품교육문화정보원', 2),
(307, 'r307', '고등어김치조림', '얼큰한 김치에 양념을 풍부하게 하여 고등어와 같이 조려보세요. 밥 한 그릇이 생각나는  요리입니다.', 20, '초보환영', 2, '조림', '한식', '205Kcal', '농림수산식품교육문화정보원', 4),
(308, 'r308', '류산슬', '녹말물을 풀어서 걸죽하게 만들어 먹는 요리랍니다..', 40, '어려움', 4, '볶음', '중국', '357Kcal', '농림수산식품교육문화정보원', 2),
(309, 'r309', '바지락볶음', '바지락을 볶아보세요. 완전히 해감시킨 후에 볶아야 모래가 씹히지 않아요.', 20, '초보환영', 4, '볶음', '한식', '175Kcal', '농림수산식품교육문화정보원', 2),
(310, 'r310', '가지쇠고기볶음', '가지랑 쇠고기가 만나서 최고의 밥반찬이 탄생했어요!', 20, '초보환영', 3, '볶음', '한식', '135Kcal', '농림수산식품교육문화정보원', 2),
(311, 'r311', '버섯청국장찌개', '구수한 청국장에 영양가 많은 버섯을 넣어 고향맛이 느껴지는 요리를 해보세요.', 30, '초보환영', 2, '찌개/전골/스튜', '한식', '117Kcal', '농림수산식품교육문화정보원', 3),
(312, 'r312', '부추부침개', '비오는 날 생각나는 부침개!', 30, '초보환영', 4, '부침', '한식', '586Kcal', '농림수산식품교육문화정보원', 2),
(313, 'r313', '냉고기쌈', '손님 접대용으로 좋아요~', 20, '초보환영', 4, '나물/생채/샐러드', '퓨전', '170Kcal', '농림수산식품교육문화정보원', 2),
(314, 'r314', '치킨버섯찜', '이젠 닭을 튀기지 말고 쪄보세요~', 40, '보통', 3, '찜', '서양', '250Kcal', '농림수산식품교육문화정보원', 3),
(315, 'r315', '새송이산적', '고급스러운  새송이를 적 요리에 응용해보세요~ 특히 어른들이 아주 좋아하는 음식이랍니다!', 20, '초보환영', 2, '구이', '한식', '234Kcal', '농림수산식품교육문화정보원', 2),
(316, 'r316', '물만두', '남녀노소 좋아하는 만두! 튀기지 않고 물만두로 즐겨보세요~', 50, '보통', 4, '만두/면류', '중국', '370Kcal', '농림수산식품교육문화정보원', 1),
(317, 'r317', '볶음쌀국수', '쌀국수를 돼지고기와 여러가지 채소를 넣어 굴소스에 볶아보세요. 굴소스를 넣을때 짜지않을 정도로만 넣으세요.', 25, '보통', 2, '만두/면류', '퓨전', '315Kcal', '농림수산식품교육문화정보원', 1),
(318, 'r318', '버섯파스타', '레스토랑에서 맛보던 파스타를 이젠, 집에서도 즐겨보세요~ 버섯도 팍팍 넣어서요!', 25, '초보환영', 2, '만두/면류', '이탈리아', '335Kcal', '농림수산식품교육문화정보원', 1),
(319, 'r319', '닭개장', '얼큰한 국물에 여러가지 나물과 담백한 닭살을 넣어 맛있게 끓인 닭개장 한그릇, 생각나시죠?', 60, '어려움', 2, '국', '한식', '171Kcal', '농림수산식품교육문화정보원', 3),
(320, 'r320', '김치볶음밥', '한국인의 입맛에 딱맞는 김치볶음밥! 편식하는 아이들 간식으로도 좋아요~', 20, '초보환영', 2, '밥', '한식', '560Kcal', '농림수산식품교육문화정보원', 1),
(321, 'r321', '오징어채볶음', '반찬이 없다구요? 냉장고에 남아있는 오징어채를 고추장에 조물조물 무쳐보세요~', 20, '초보환영', 3, '볶음', '한식', '130Kcal', '농림수산식품교육문화정보원', 2),
(322, 'r322', '바지락칼국수', '바지락으로 시원한 국물맛을 내고, 쫄깃한 면발에 칼국수를 색다르게 먹을 수 있는 요리랍니다.', 25, '초보환영', 3, '만두/면류', '한식', '420Kcal', '농림수산식품교육문화정보원', 1),
(323, 'r323', '오징어도라지생채', '도라지의 아삭함과 오징어의 고소함을 같이 느껴 보세요.', 30, '초보환영', 2, '나물/생채/샐러드', '한식', '140Kcal', '농림수산식품교육문화정보원', 2),
(324, 'r324', '애호박무침', '새우젓을 첨가해 애호박을 무쳐보세요~ 밥반찬으로 좋습니다.', 15, '초보환영', 3, '볶음', '한식', '85Kcal', '농림수산식품교육문화정보원', 2),
(325, 'r325', '양송이버섯죽', '아침식사로도 환자식으로도 좋습니다!', 30, '초보환영', 2, '밥', '한식', '224Kcal', '농림수산식품교육문화정보원', 1),
(326, 'r326', '홍합미역국', '홍합의 시원한 맛이 미역국의 맛을 한층 더해준답니다.', 20, '보통', 4, '국', '한식', '80Kcal', '농림수산식품교육문화정보원', 3),
(327, 'r327', '오징어덮밥', '쫄깃한 오징어와 매콤한 양념의 환상조합으로 밥 한 공기 뚝딱!', 30, '보통', 2, '밥', '한식', '445Kcal', '농림수산식품교육문화정보원', 1),
(328, 'r328', '모듬채소볶음', '모듬 채소들이 다 모였습니다! 수분이 생기지 않게 얼른 볶아 삼삼하게 간해주세요~', 20, '초보환영', 2, '볶음', '서양', '165Kcal', '농림수산식품교육문화정보원', 2),
(329, 'r329', '대구탕', '얼큰한 국물에 담백한 생선을 넣어 보글보글 맛있게 끓였어요. 추운 날씨에 한 그릇 뚝딱!', 30, '보통', 2, '국', '한식', '170Kcal', '농림수산식품교육문화정보원', 3),
(330, 'r330', '불고기찹쌀구이', '부드러운 육질에 찹쌀로 쫄깃함을 입힌 불고기 찹쌀구이! 오늘의 별식으로 어떠신가요?', 30, '보통', 2, '구이', '한식', '268Kcal', '농림수산식품교육문화정보원', 2),
(331, 'r331', '고추부각', '고추의 매운맛이 사라지고 바삭한 맛이 탄생했어요~', 30, '어려움', 2, '튀김/커틀릿', '한식', '110Kcal', '농림수산식품교육문화정보원', 2),
(332, 'r332', '충무김밥', '김밥에 오징어 초무침을 곁들여보세요~', 50, '보통', 2, '밥', '한식', '450Kcal', '농림수산식품교육문화정보원', 1),
(333, 'r333', '기스면', '특이한 면 요리를 원하신다면, 결코 어렵지 않은 조리법으로 특이한 음식을 맛볼 수 있답니다!', 30, '보통', 2, '만두/면류', '중국', '189Kcal', '농림수산식품교육문화정보원', 1),
(334, 'r334', '감자수프', '감자를 맛있게 갈아 따끈하고 부드러운 수프를 즐겨보세요~', 40, '보통', 2, '밥', '서양', '265Kcal', '농림수산식품교육문화정보원', 1),
(335, 'r335', '마늘빵', '마늘빵을 집에서 정성스럽게 만들어 보세요.', 20, '초보환영', 2, '빵/과자', '서양', '276Kcal', '농림수산식품교육문화정보원', 3),
(336, 'r336', '치킨수프', '속이 더부룩할때는 간단한 수프로 속을 편하게 지켜주세요! 수프 한 그릇이 든든한 한끼가 된답니다.', 40, '보통', 2, '밥', '중국', '275Kcal', '농림수산식품교육문화정보원', 1),
(337, 'r337', '계란찜', '여러가지 야채들과 완전단백식품 계란으로 간단한 찜요리를 해보세요~ 부드러운 아침식사로 너무 좋아요!', 20, '초보환영', 2, '찜', '한식', '98Kcal', '농림수산식품교육문화정보원', 3),
(338, 'r338', '콩나물비빔밥', '콩나물을 넣은 맛있는 비빔밥을 만들어 보세요. 아삭하게 씹히는 콩나물 맛이 정말 색다르답니다.', 40, '보통', 1, '밥', '한식', '385Kcal', '농림수산식품교육문화정보원', 1),
(339, 'r339', '인절미', '옛날처럼 큰 절구는 없어도 조그마한 절구로 인절미를 만들어 보세요.', 60, '초보환영', 1, '떡/한과', '한식', '175Kcal', '농림수산식품교육문화정보원', 2),
(340, 'r340', '상추채소무침', '상추채소무침에 된장을 넣고 밥비벼 먹어보세요~', 20, '초보환영', 2, '나물/생채/샐러드', '한식', '85Kcal', '농림수산식품교육문화정보원', 2),
(341, 'r341', '호박양파국', '매일 먹는 국이 지겨우시다면 호박과 양파를 넣어서 색다른 국을 끓여 보세요.', 20, '초보환영', 2, '국', '한식', '73Kcal', '농림수산식품교육문화정보원', 3),
(342, 'r342', '꽁치구이', '꽁치를 가장 신선하게 맛있게 먹을 수 있답니다. 소금을 적당하게 뿌려서 그릴에 구워 바로 드세요~!', 20, '초보환영', 2, '구이', '한식', '183Kcal', '농림수산식품교육문화정보원', 2),
(343, 'r343', '오징어젓갈', '밥도둑의 대표명사!', 40, '초보환영', 2, '밑반찬/김치', '한식', '54Kcal', '농림수산식품교육문화정보원', 4),
(344, 'r344', '무생채', '새콤달콤하게 무쳐서 밥상위에 올려 놓으면 인기 짱!', 20, '초보환영', 2, '나물/생채/샐러드', '한식', '55Kcal', '농림수산식품교육문화정보원', 2),
(345, 'r345', '해물국시', '해물이 듬뿍 들어가서 너무 너무 시원해요.', 60, '보통', 2, '만두/면류', '한식', '295Kcal', '농림수산식품교육문화정보원', 1),
(346, 'r346', '안심스테이크', '기념일날 분위기 있게 스테이크를 집에서 만들어 보세요.', 40, '보통', 2, '양식', '서양', '250Kcal', '농림수산식품교육문화정보원', 2),
(347, 'r347', '파래무침', '해조류가 다이어트에 좋은거 알고계시죠? 새콤 달콤하게 무쳐보세요.', 20, '초보환영', 2, '밑반찬/김치', '한식', '38Kcal', '농림수산식품교육문화정보원', 4),
(348, 'r348', '단호박튀김', '아이들이 호박은 싫어하죠? 튀겨내면 아이들이 정말~ 좋아합니다!', 30, '초보환영', 2, '튀김/커틀릿', '한식', '157Kcal', '농림수산식품교육문화정보원', 2),
(349, 'r349', '해물스파게티', '레스토랑에서 즐기던 스파게티! 이젠 집에서도 즐겨보세요~ 홍합 골라 먹는 재미가 솔솔~', 30, '초보환영', 2, '만두/면류', '서양', '523Kcal', '농림수산식품교육문화정보원', 1),
(350, 'r350', '월남쌈', '베트남 음식이 생소하시다구요?? 이 방법대로만 하면 OK!', 30, '보통', 2, '나물/생채/샐러드', '동남아시아', '295Kcal', '농림수산식품교육문화정보원', 2),
(351, 'r351', '무나물', '무를 담백하게 볶아봤어요. 어때요 맛있죠?', 20, '초보환영', 2, '나물/생채/샐러드', '한식', '43Kcal', '농림수산식품교육문화정보원', 2),
(352, 'r352', '고등어된장조림', '조림 고등어도 맛있지만 곁들여진 무에 간이 배면 더욱더 맛있죠.', 40, '보통', 2, '조림', '한식', '192Kcal', '농림수산식품교육문화정보원', 4),
(353, 'r353', '두부두루치기', '두부로 두루치기를 만들때는 두부의 모양에 신경써 주세요^^', 20, '초보환영', 2, '볶음', '한식', '198Kcal', '농림수산식품교육문화정보원', 2),
(354, 'r354', '고구마그라탱', '고구마로 만든 별미디저트를 소개할게요. 찐고구마와 생크림, 치즈를 섞어 피자치즈를 뿌려 다시 고소하게 구워낸 고구마그라탱 별미중에 별미랍니다!!', 30, '초보환영', 2, '그라탕/리조또', '서양', '196Kcal', '농림수산식품교육문화정보원', 2),
(355, 'r355', '시금치된장죽', '다시마와 가쓰오부시를 우려낸 국물에 왜된장을 살살 풀어 데쳐낸 시금치를 넣어 만든 된장국에 쌀을 넣어 만든 죽이에요.', 30, '초보환영', 2, '밥', '한식', '185Kcal', '농림수산식품교육문화정보원', 1),
(356, 'r356', '제육겨자쌈', '영양가 많게 쌈을 먹고 싶을때~', 60, '보통', 2, '나물/생채/샐러드', '한식', '155Kcal', '농림수산식품교육문화정보원', 2),
(357, 'r357', '그린파스타', '색다를 음식을 식사로 하고 싶을 때 도전해 보세요.. 색다른 맛에 반하실 꺼예요.', 30, '초보환영', 2, '만두/면류', '이탈리아', '423Kcal', '농림수산식품교육문화정보원', 1),
(358, 'r358', '삼색태극말이초밥', '피크닉을 위해 준비할 수 있는 깜찍한 요리.', 30, '보통', 2, '밥', '일본', '345Kcal', '농림수산식품교육문화정보원', 1),
(359, 'r359', '캘리포니아롤', '게를 가지고 피크닉에 갈 수는 없을까요? 확인해 보세요^^', 60, '보통', 2, '밥', '일본', '387Kcal', '농림수산식품교육문화정보원', 1),
(360, 'r360', '오곡주먹밥', '밥맛없어 하는 아이들의 눈길을 끌어 보세요.', 30, '초보환영', 2, '밥', '한식', '349Kcal', '농림수산식품교육문화정보원', 1),
(361, 'r361', '무초김치', '맵지 않은 김치를 한번 만들어 볼까요?', 30, '초보환영', 3, '밑반찬/김치', '한식', '246Kcal', '농림수산식품교육문화정보원', 4),
(362, 'r362', '화전', '옛부터 내려오는 음식이죠? 꽃을 전 위에 살짝~', 30, '초보환영', 2, '떡/한과', '한식', '230Kcal', '농림수산식품교육문화정보원', 2),
(363, 'r363', '만두샐러드', '만두를 바삭하게튀겨 신선한 야채와 샐러드를 만들어보세요..달콤한 허니머스터드 드레싱을 곁들여 먹으면 더욱 맛있답니다.', 30, '초보환영', 2, '나물/생채/샐러드', '퓨전', '370Kcal', '농림수산식품교육문화정보원', 2),
(364, 'r364', '콩나물미나리무침', '오물조물 콩나물에 향긋한 미나리를 넣어 무쳐보세요. 미나리의 초록색에 아삭한 콩나물이 너무 잘 어울린답니다.', 20, '초보환영', 2, '밑반찬/김치', '한식', '75Kcal', '농림수산식품교육문화정보원', 4),
(365, 'r365', '돈부리', '달짝지근하면서 짭조름하면서 구수하면서  일본의 돈부리한그릇 한번 드셔보세요~', 30, '보통', 2, '밥', '일본', '456Kcal', '농림수산식품교육문화정보원', 1),
(366, 'r366', '연어알초밥', '입안에서 톡톡 터지는 연어알을 초밥위에 예쁘게 장식하세요!', 30, '초보환영', 1, '밥', '일본', '261Kcal', '농림수산식품교육문화정보원', 1),
(367, 'r367', '깐풍새우', '매콤하고 새콤한 새우요리!! 손님접대용으로 그만이랍니다^^', 40, '보통', 2, '튀김/커틀릿', '중국', '286Kcal', '농림수산식품교육문화정보원', 2),
(368, 'r368', '해산물두부수프', '신선한 새우와 오징어등의 해산물의 단백한 국물맛을 느껴보세요.', 30, '초보환영', 2, '밥', '중국', '295Kcal', '농림수산식품교육문화정보원', 1),
(369, 'r369', '채소스프', '토마토 소스의 깔끔하고 부드러운 스프~', 30, '초보환영', 2, '밥', '서양', '265Kcal', '농림수산식품교육문화정보원', 1),
(370, 'r370', '샤브샤브', '깔끔하고 간편한 요리를 하고 싶을때 샤브샤브 어떠세요?', 30, '초보환영', 2, '찌개/전골/스튜', '일본', '220Kcal', '농림수산식품교육문화정보원', 3),
(371, 'r371', '소바정식', '쫄깃한 모밀에 시원한 소스를 곁들여 먹으면 정말 맛있어요. 특히 여성분들이 너무 좋아한답니다!', 20, '초보환영', 2, '만두/면류', '일본', '392Kcal', '농림수산식품교육문화정보원', 1),
(372, 'r372', '쇠고기버섯덮밥', '간단하게 고급스러운 소바정식을 맛볼 수있다면 여러가지 버섯이 들어가 더욱 맛있답니다.', 30, '초보환영', 2, '밥', '일본', '385Kcal', '농림수산식품교육문화정보원', 1),
(373, 'r373', '꽃게해물탕', '매콤하고 시원한 국물의 꽃게탕. 젓가락으로 꽃게살을 쏙쏙 빼먹는 맛은 별미랍니다.', 30, '보통', 2, '찌개/전골/스튜', '한식', '145Kcal', '농림수산식품교육문화정보원', 3),
(374, 'r374', '해초무침', '상큼한 사과 소스에 신선한 해초를 담아 맛있는 산뜻한 샐러드를 만들어 보세요.', 20, '초보환영', 2, '나물/생채/샐러드', '일본', '95Kcal', '농림수산식품교육문화정보원', 2),
(375, 'r375', '모듬전', '담백하고 맛있는 감자전과 향이 너무 좋은 깻잎전. 달콤한 양파로 맛있는 전을 부쳐보세요.', 30, '초보환영', 2, '부침', '한식', '210Kcal', '농림수산식품교육문화정보원', 2),
(376, 'r376', '장어덮밥', '더운 여름이 다가오고 있어요. 몸보신을 위해서 맛난 장어덮밥을 만들어 보세요.', 30, '초보환영', 2, '밥', '일본', '412Kcal', '농림수산식품교육문화정보원', 1),
(377, 'r377', '장어계란말이', '부드러운 계란에 장어를 넣어 말았답니다. 조금은 특별한 맛이 느껴지고요.', 30, '초보환영', 2, '밑반찬/김치', '일본', '311Kcal', '농림수산식품교육문화정보원', 4),
(378, 'r378', '토마토해산물스파게티', '시원하고 영양이 풍부한 해산물로 스파게티를 만들었답니다. 새콤달콤 토마토 소스를 만들어 쫄깃한 스파게티에 솔솔~', 30, '초보환영', 2, '만두/면류', '이탈리아', '356Kcal', '농림수산식품교육문화정보원', 1),
(379, 'r379', '돈까스덮밥', '바삭하게 튀긴 돈까스를 밥위에 얹어서 드셔보세요. 아주 별미랍니다.', 30, '초보환영', 2, '밥', '일본', '498Kcal', '농림수산식품교육문화정보원', 1),
(380, 'r380', '볶음우동', '매콤한 소스를 쫄깃한 우동면에 뿌려드세요. 아삭하게 씹히는 야채가 들어가 더욱 맛있답니다.', 30, '초보환영', 2, '만두/면류', '일본', '312Kcal', '농림수산식품교육문화정보원', 1),
(381, 'r381', '오징어삼겹살볶음', '육류와 해산물의 환상적인 조합! 매콤하니 좋아요~', 30, '초보환영', 2, '볶음', '한식', '325Kcal', '농림수산식품교육문화정보원', 2),
(382, 'r382', '채소영양밥', '견과류를 이용한 구수하고 맛있는 영양밥을 만들어 보아요.', 50, '초보환영', 2, '밥', '한식', '362Kcal', '농림수산식품교육문화정보원', 1),
(383, 'r383', '마파두부덮밥', '매콤한 두반장 소스에 부드러운 두부의 감칠맛~ 따끈한 밥위에 얹어 내세요.', 30, '보통', 3, '밥', '중국', '485Kcal', '농림수산식품교육문화정보원', 1),
(384, 'r384', '순두부', '따뜻한 김이 모락모락 나는 순두부에 감칠맛나는 간장양념을 살짝 비벼 먹는 그 맛~', 50, '보통', 4, '찌개/전골/스튜', '한식', '630Kcal', '농림수산식품교육문화정보원', 3),
(385, 'r385', '우묵냉채', '더운 여름에는 시원한 우묵냉채를 만들어 보세요. 입맛이 확 당긴답니다~', 20, '초보환영', 2, '나물/생채/샐러드', '한식', '78Kcal', '농림수산식품교육문화정보원', 2),
(386, 'r386', '버섯매운탕', '얼큰한 국물에 영양가 많은 버섯을 넣어 요리해보세요. 마지막에는 밥을 넣어 볶음밥까지 먹을 수있답니다.', 60, '보통', 2, '만두/면류', '한식', '312Kcal', '농림수산식품교육문화정보원', 1),
(387, 'r387', '동래파전', '식구들이 둘러 앉아 맛있는 동래파전을 만들어 드셔보세요. 오붓한 정감과 함께 맛을 느껴보세요.', 30, '초보환영', 2, '부침', '한식', '421Kcal', '농림수산식품교육문화정보원', 2),
(388, 'r388', '조기찜', '영양가 풍부한 조기로 맛있는 찜을 만들어 보세요. 반찬으로 너무 좋답니다~', 30, '초보환영', 2, '찜', '한식', '297Kcal', '농림수산식품교육문화정보원', 3),
(389, 'r389', '양상추참치샐러드', '아삭하게 씹히는 양상추 위에 맛있게 묻힌 참치 샐러드를~', 20, '초보환영', 2, '나물/생채/샐러드', '서양', '271Kcal', '농림수산식품교육문화정보원', 2),
(390, 'r390', '라조육', '라조육의 라조는 고추를, 육은 돼지고기를 양념해 튀겨서 매운맛을 낸 음식이랍니다.', 30, '초보환영', 2, '튀김/커틀릿', '중국', '412Kcal', '농림수산식품교육문화정보원', 2),
(391, 'r391', '김치홍합국', '김치의 시원한 맛에 홍합을 넣어 한소끔 끓여 준비해보세요. 속풀이 음식으로 안성맞춤!', 30, '초보환영', 2, '국', '한식', '129Kcal', '농림수산식품교육문화정보원', 3),
(392, 'r392', '가지튀김', '가지에 갈은 돼지고기를 넣어 바삭하게 튀겨보세요. 머스터드 드레싱을 곁들이면 더 맛있는 요리가 되지요.', 30, '초보환영', 2, '튀김/커틀릿', '한식', '364Kcal', '농림수산식품교육문화정보원', 2),
(393, 'r393', '골뱅이볶음', '색다른 골뱅이볶음을 만들어 보세요. 술안주로 아주 그만이지요.', 30, '초보환영', 2, '볶음', '한식', '255Kcal', '농림수산식품교육문화정보원', 2),
(394, 'r394', '닭가슴살해파리샐러드', '영양많은 닭살에 새콤달콤 해파리를 넣어 맛있게 무쳐보세요. 손님 상차림으로 안성맞춤!', 30, '초보환영', 2, '나물/생채/샐러드', '한식', '198Kcal', '농림수산식품교육문화정보원', 2),
(395, 'r395', '어묵볶음', '얼큰한 김치와 어묵을 같이 볶아보세요. 어묵은 일단 기름을 한번 빼고 김치와 같이 볶아줍니다.', 30, '초보환영', 2, '볶음', '한식', '138Kcal', '농림수산식품교육문화정보원', 2),
(396, 'r396', '오징어섞어찌개', '얼큰한 오징어에 여러가지 채소를 넣어 맛나게 끓여보세요. 모시조개가 시원한 맛을 더해준답니다.', 30, '초보환영', 2, '찌개/전골/스튜', '한식', '369Kcal', '농림수산식품교육문화정보원', 3),
(397, 'r397', '떡꼬치', '맛있는 떡꼬치를 집에서 만들어 보세요. 아이들이 너무 좋아하는 간식이랍니다.', 30, '초보환영', 4, '구이', '한식', '299Kcal', '농림수산식품교육문화정보원', 2),
(398, 'r398', '연어오픈샌드위치', '고급스러운 연어로 맛있는 샌드위치를 만들어 보세요. 도시락으로 너무 좋아요^^', 30, '초보환영', 2, '샌드위치/햄버거', '서양', '399Kcal', '농림수산식품교육문화정보원', 1),
(399, 'r399', '참치김치찌개', '간단하고 쉬운 참치김치찌개를 만들어 보세요. 얼큰한 맛을 더하려면 고춧가루를 좀 더 넣어주세요~', 30, '초보환영', 2, '찌개/전골/스튜', '한식', '186Kcal', '농림수산식품교육문화정보원', 3),
(400, 'r400', '오징어볶음과소면', '매콤하게 고추장과 고춧가루를 넣어 술안주로 너무 좋은 오징어볶음을 만들어보세요.', 30, '초보환영', 2, '볶음', '한식', '236Kcal', '농림수산식품교육문화정보원', 2);

INSERT INTO recipe (id, code, title, description, cook_time_min, difficulty, servings, category, cuisine, kcal, source, storage_days) VALUES
(401, 'r401', '부추잡채', '향긋하고 먹음직스런 싱싱한 부추를 깨끗한 맛이 담긴 청정원 굴소스로 요리해보세요~', 30, '초보환영', 2, '볶음', '한식', '206Kcal', '농림수산식품교육문화정보원', 2),
(402, 'r402', '쟁반라면', '푸짐한 쟁반라면을 만들어 보세요. 꼬들꼬들하게 라면을 삶아서 아삭한 야채와 함께 준비하며 더욱 맛있는 요리가 되지요~', 40, '초보환영', 2, '만두/면류', '한식', '415Kcal', '농림수산식품교육문화정보원', 1),
(403, 'r403', '불고기꽃만두', '치자로 예쁜 색깔을 내어 특별한 만두를 만들어 보세요.', 30, '초보환영', 2, '만두/면류', '퓨전', '421Kcal', '농림수산식품교육문화정보원', 1),
(404, 'r404', '해물샤브샤브', '온가족이 둘러 앉아 해물을 육수에 퐁당퐁당! 간단하게 준비하여 푸짐하게 드실 수 있답니다', 30, '초보환영', 2, '찌개/전골/스튜', '일본', '296Kcal', '농림수산식품교육문화정보원', 3),
(405, 'r405', '간장게장', '담백하고 짜지 않은 간장게장을 만들어보세요. 밥도둑이 따로 없답니다.', 60, '보통', 2, '밑반찬/김치', '한식', '136Kcal', '농림수산식품교육문화정보원', 4),
(406, 'r406', '녹두죽', '건강에 좋은 죽을 요리해보세요. 입맛이 없을때 한그릇 뚝딱!', 60, '초보환영', 2, '밥', '한식', '280Kcal', '농림수산식품교육문화정보원', 1),
(407, 'r407', '돼지불고기', '저녁 반찬 뭐 해먹을까? 오늘 저녁 반찬으로 딱 어울리는 요리. 돼지불고기를 준비해보세요.', 30, '초보환영', 2, '볶음', '한식', '220Kcal', '농림수산식품교육문화정보원', 2),
(408, 'r408', '단호박구이', '단호박으로 맛있는 간식을 만들어보세요. 단호박의 부드러운 맛과 달콤한 맛이 너무 잘 어울려요.', 30, '초보환영', 2, '구이', '한식', '215Kcal', '농림수산식품교육문화정보원', 2),
(409, 'r409', '라조기', '늘 시켜먹던 라조기를 직접 만들어 보세요. 바삭하게 튀긴 닭에 맛있는 소스를 곁들이면 정말 맛있는 라조기가 되지요.', 40, '초보환영', 2, '튀김/커틀릿', '중국', '341Kcal', '농림수산식품교육문화정보원', 2),
(410, 'r410', '양파쌈파이', '우리 몸에 좋은 양파를 만두피에 넣어 바삭하게 튀겨보세요. 정말 색다른 맛이랍니다.', 30, '초보환영', 2, '튀김/커틀릿', '퓨전', '321Kcal', '농림수산식품교육문화정보원', 2),
(411, 'r411', '미역수제비', '미역국에 수제비를 넣고 끓여보세요! 색다른 맛이랍니다.', 40, '초보환영', 2, '만두/면류', '한식', '358Kcal', '농림수산식품교육문화정보원', 1),
(412, 'r412', '맑은대구탕', '추운 겨울에 딱 어울리는 국물요리랍니다. 시원하게 다시마로 국물을 우려내고 맛있는 생대구를 넣어보세요.', 40, '초보환영', 2, '국', '한식', '165Kcal', '농림수산식품교육문화정보원', 3),
(413, 'r413', '브로콜리베이컨말이', '술안주나 아이들 간식으로 너무 좋은 브로콜리 베이컨 말이~ 정말 맛있어요.', 30, '보통', 2, '구이', '서양', '280Kcal', '농림수산식품교육문화정보원', 2),
(414, 'r414', '쇠고기덮밥', '밥을 고소한 참기름, 깨소금에 볶아서 맛있게 양념한 불고기와 같이 준비해보세요.', 30, '초보환영', 2, '밥', '한식', '396Kcal', '농림수산식품교육문화정보원', 1),
(415, 'r415', '고등어튀김케첩조림', '단백질이 풍부한 고등어를 바삭하게 튀겨서.. 맛있는 소스에 버무려 내세요...', 30, '초보환영', 2, '조림', '한식', '410Kcal', '농림수산식품교육문화정보원', 4),
(416, 'r416', '생굴채소무침', '우리식으로 다양하게 굴요리를 만들어보세요~', 30, '보통', 1, '나물/생채/샐러드', '한식', '250Kcal', '농림수산식품교육문화정보원', 2),
(417, 'r417', '생선전', '담백한 대구살로 맛있는 전을 부쳐보세요. 고급스러운 맛을 더하려면 쑥갓을 한잎~', 30, '초보환영', 2, '부침', '한식', '166Kcal', '농림수산식품교육문화정보원', 2),
(418, 'r418', '통마늘장아찌', '반찬용으로 새콤달콤하게 만들어보세요~', 40, '초보환영', 2, '밑반찬/김치', '한식', '56Kcal', '농림수산식품교육문화정보원', 4),
(419, 'r419', '북어해장국밥', '포송포송한 북어로 담백한 북어해장국밥을 만들어보세요. 아침식사로 아주 그만이죠!', 30, '보통', 2, '밥', '한식', '493Kcal', '농림수산식품교육문화정보원', 1),
(420, 'r420', '봄동겉절이', '뜨거운 밥위에 겉절이를 맛있게 올려 먹으면 없던 입맛이 새록새록 살아납니다! 봄동의 향긋한 향도 너무 좋아요.', 30, '초보환영', 2, '밑반찬/김치', '한식', '78Kcal', '농림수산식품교육문화정보원', 4),
(421, 'r421', '양파전', '쇠고기를 곱게 다져서 소를 만들어 아삭한 양파안에 채워넣지요. 기름에 노릇하게 구워내면 아주 맛있는 양파전이 됩니다!', 30, '초보환영', 2, '부침', '한식', '165Kcal', '농림수산식품교육문화정보원', 2),
(422, 'r422', '꽃상추쌈', '싱싱한 상추를 준비하여 그 위에 맛있게 양념한 밥을 올려보세요~ 모양도 굿 맛도 굿!', 30, '초보환영', 2, '밥', '한식', '352Kcal', '농림수산식품교육문화정보원', 1),
(423, 'r423', '돼지고기우엉말이조림', '영양가 풍부한 돼지고기에 우엉을 넣어 돌돌 말았답니다. 맛있는 양념간장에 조려보세요! 밥반찬으로도 너무 좋구요~', 30, '초보환영', 2, '조림', '한식', '170Kcal', '농림수산식품교육문화정보원', 4),
(424, 'r424', '다시마채소말이', '다이어트를 하신다면 깔끔한 다시마 야채 말이를 만들어보세요! 여러가지 야채와 다시마가 아주 잘 어울려요.', 30, '초보환영', 2, '나물/생채/샐러드', '한식', '123Kcal', '농림수산식품교육문화정보원', 2),
(425, 'r425', '무말랭이무침', '양념장을 맛있게 만들어 무말랭이를 맛있게 조물조물 무쳐보세요.', 20, '초보환영', 2, '밑반찬/김치', '한식', '69Kcal', '농림수산식품교육문화정보원', 4),
(426, 'r426', '낙지불고기', '낙지와 불고기가 만났다? 낙지와 불고기를 맛있게 양념해서 얼큰하고 담백한 전골 요리를 해보세요.', 40, '초보환영', 2, '볶음', '한식', '393Kcal', '농림수산식품교육문화정보원', 2),
(427, 'r427', '돌솥비빔밥', '뜨근한 돌솥에 여러가지 재료들을 넣어 맛있는 돌솥비빔밥을 만들어보세요~', 30, '초보환영', 2, '밥', '한식', '521Kcal', '농림수산식품교육문화정보원', 1),
(428, 'r428', '고등어양념구이', '고등어에 양념장 솔솔 발라서 중불이나 약불에서 구워보세요.', 30, '초보환영', 2, '구이', '한식', '175Kcal', '농림수산식품교육문화정보원', 2),
(429, 'r429', '고등어조림', '오늘 저녁에는 고등어조림으로 밥 한끼 해결합시다. 간이 밴 무도 맛이 일품이죠~', 30, '초보환영', 2, '조림', '한식', '250Kcal', '농림수산식품교육문화정보원', 4),
(430, 'r430', '갈치구이', '갈치구이를 접시에 담을 땐 레몬을 한조각 올려서 더욱 이쁘게! 보기 좋은게 먹기도 좋답니다~', 15, '초보환영', 2, '구이', '한식', '165Kcal', '농림수산식품교육문화정보원', 2),
(431, 'r431', '갈치조림', '밥 한그릇 생각나게 하는 갈치조림이죠!', 30, '초보환영', 2, '조림', '한식', '240Kcal', '농림수산식품교육문화정보원', 4),
(432, 'r432', '새우겨자채', '톡쏘는 겨자소스에 버무린 오동통한 새우가 참 맛있답니다.', 30, '초보환영', 2, '나물/생채/샐러드', '한식', '135Kcal', '농림수산식품교육문화정보원', 2),
(433, 'r433', '치즈멸치볼', '치즈와 멸치가 들어가서 칼슘과 단백질이 아주 아주 풍부한 요리입니다. 아이들의 오늘 간식은 치즈멸치볼로 해결하세요.', 20, '초보환영', 2, '밥', '퓨전', '287Kcal', '농림수산식품교육문화정보원', 1),
(434, 'r434', '채소치즈죽', '아침을 꼭꼭 챙겨먹어야지만이 하루도 든든하고 머리회전도 빨라진데요. 채소치즈죽으로 아침 절대 거르지 마세요~', 20, '초보환영', 1, '밥', '퓨전', '268Kcal', '농림수산식품교육문화정보원', 1),
(435, 'r435', '수삼치즈샐러드', '힘이 불끈 솟아나는 수삼과 비타민이 풍부한 야채들을 넣어 상큼하게 버무린 수삼치즈샐러드로 잃어버린 입맛을 살리세요~', 20, '초보환영', 2, '나물/생채/샐러드', '퓨전', '264Kcal', '농림수산식품교육문화정보원', 2),
(436, 'r436', '마늘볶음국수', '마늘을 버터에 볶으면 고소하고도 향긋한 맛이 일품이예요. 생숙주를 넣어서 더욱 맛을 낸 퓨전요리를 소개합니다.', 30, '초보환영', 2, '밥', '퓨전', '450Kcal', '농림수산식품교육문화정보원', 1),
(437, 'r437', '쌀국수', '베트남 고유의 시원한 쌀국수 요리를 우리집 가정에서 느껴보세요~ 담백한 육수와 상큼한 숙주가 일품이예요!', 30, '초보환영', 2, '만두/면류', '동남아시아', '385Kcal', '농림수산식품교육문화정보원', 1),
(438, 'r438', '깻잎조림', '깻잎을 이용한 쉽고 간단한 밑반찬입니다. 밥도둑이 따로 없어요~', 15, '초보환영', 2, '밑반찬/김치', '한식', '53Kcal', '농림수산식품교육문화정보원', 4),
(439, 'r439', '얼갈이열무물김치', '여름철엔 시원한 열무김치를 넣고 국수에 말아 먹으면 정말 어떤 음식도 부럽지 않죠.', 60, '보통', 4, '밑반찬/김치', '한식', '65Kcal', '농림수산식품교육문화정보원', 4),
(440, 'r440', '간장', '한식에 없어서는 안될 간장! 메주를 소금물에 넣고 숙성시키면 신기하게도 까만 간장이 탄생한답니다~', 5, '어려움', 2, '양념장', '한식', '40Kcal', '농림수산식품교육문화정보원', 7),
(441, 'r441', '된장', '간장을 담았던 메주를 덜어 내서 소금에 버무려 된장이 되죠. 오래도록 숙성시켜서 먹는 대표적인 슬로우 푸드이자 양질의 단백질 공급원! 된장을 함께 만들어 보아요~', 30, '어려움', 4, '양념장', '한식', '32Kcal', '농림수산식품교육문화정보원', 7),
(442, 'r442', '고추장', '입맛 없을 때, 고추장에 슥슥 비벼 밥 한 공기 뚝딱! 고추장, 이젠 사지 말고 직접 만들어 보세요~', 90, '어려움', 4, '양념장', '한식', '52Kcal', '농림수산식품교육문화정보원', 7),
(443, 'r443', '고구마강정', '달콤한 고구마를 기름에 튀겨 고소해지게 하고 또 달콤한 건포도와 고소한 호박씨를 넣어 시럽을 만들어 굳혀 보세요.', 60, '보통', 4, '도시락/간식', '한식', '580Kcal', '농림수산식품교육문화정보원', 1),
(444, 'r444', '근대된장국', '담백하고 시원한 근대된장국으로 밥 한그릇 뚝딱 해결해 보세요.', 30, '초보환영', 2, '국', '한식', '42Kcal', '농림수산식품교육문화정보원', 3),
(445, 'r445', '된장찌개', '구수한 냄새, 고소한 맛! 한국의 대표음식 된장찌개! 우리 입맛에 딱이예요~', 30, '초보환영', 2, '찌개/전골/스튜', '한식', '136Kcal', '농림수산식품교육문화정보원', 3),
(446, 'r446', '깻잎말이김치', '갖가지 재료를 넣고 돌돌 말아서 멸치액젓에 절였어요. 고급스러운 김치로 아주 맛있답니다.', 30, '초보환영', 4, '밑반찬/김치', '한식', '82Kcal', '농림수산식품교육문화정보원', 4),
(447, 'r447', '붉은갓동치미', '붉은 갓에서 배어나온 자주빛의 국물이 미각과 시각을 모두 만족시켜주는 시원한 김치예요.', 30, '초보환영', 4, '밑반찬/김치', '한식', '76Kcal', '농림수산식품교육문화정보원', 4),
(448, 'r448', '파프리카볶음밥', '형형색깔의 파프리카 속에 볶음밥으로 아이들도 참 좋아해요.', 50, '초보환영', 2, '밥', '퓨전', '326Kcal', '농림수산식품교육문화정보원', 1),
(449, 'r449', '돼지갈비레몬찜', '새콤한 레몬을 곁들인 돼지갈비찜으로 식탁을 풍성하게 만들어 보세요.', 60, '초보환영', 2, '찜', '퓨전', '420Kcal', '농림수산식품교육문화정보원', 3),
(450, 'r450', '시금치계란말이', '뽀빠이처럼 튼튼하게 자랄 수 있는 아이들 건강식 반찬 요리입니다.', 30, '초보환영', 2, '부침', '한식', '109Kcal', '농림수산식품교육문화정보원', 2),
(451, 'r451', '낙지연포탕', '낙지와 모시조개 덕분에 바다향 가득한 시원한 국물~', 30, '초보환영', 4, '찌개/전골/스튜', '한식', '152Kcal', '농림수산식품교육문화정보원', 3),
(452, 'r452', '새우죽', '부드러운 죽 한그릇으로 아침을 거르지 마세요. 소화가 잘 되어서 환자식으로도 참 좋아요.', 30, '초보환영', 2, '밥', '한식', '278Kcal', '농림수산식품교육문화정보원', 1),
(453, 'r453', '전복죽', '쫄깃한 전복살과 깊은 감칠맛이 입 안에 맴도는 보양식 죽 대령이오~', 30, '초보환영', 2, '밥', '한식', '275Kcal', '농림수산식품교육문화정보원', 1),
(454, 'r454', '죽순회와미나리강회', '죽순의 아삭거림과 초고추장의 새콤달콤~ 미나리의 상큼한 맛이 입맛을 살려줘요!', 20, '초보환영', 2, '나물/생채/샐러드', '한식', '165Kcal', '농림수산식품교육문화정보원', 2),
(455, 'r455', '시금치나물', '개운하게 나물을 무쳐보세요! 액젓으로 간해 맛이 깔끔하답니다!', 20, '초보환영', 2, '밑반찬/김치', '한식', '37Kcal', '농림수산식품교육문화정보원', 4),
(456, 'r456', '녹차콩국수', '다시마와 가쓰오부시의 육수가 섞인 콩국에 쌉싸름한 맛의 녹차국수가 섞여 색다른 퓨전요리의 맛을 느껴보세요~', 30, '보통', 2, '만두/면류', '한식', '430Kcal', '농림수산식품교육문화정보원', 1),
(457, 'r457', '우무콩냉국', '우무는 저칼로리 식품일뿐만 아니라 섬유질이 풍부해 배변활동을 도와 주는 다이어트 식품입니다.', 20, '초보환영', 4, '국', '한식', '82Kcal', '농림수산식품교육문화정보원', 3),
(458, 'r458', '모듬콩수프', '단백질 덩어리 몸에 좋은 콩콩콩! 부드러운 수프로 즐겨보세요~', 20, '초보환영', 2, '밥', '서양', '260Kcal', '농림수산식품교육문화정보원', 1),
(459, 'r459', '서리태콩국수', '여름 더위를 물리치는 단골손님, 시원한 콩국수! 쫄깃한 면발과 고소한 국물맛이 환상이죠.', 30, '초보환영', 2, '만두/면류', '한식', '489Kcal', '농림수산식품교육문화정보원', 1),
(460, 'r460', '대대로닭칼국수', '닭육수로 만든 시원한 국물맛과 콩가루로 빚은 고소한 면발이 잘 어울리는 따끈따끈한 칼국수 대령이요!', 30, '초보환영', 2, '만두/면류', '한식', '235Kcal', '농림수산식품교육문화정보원', 1),
(461, 'r461', '전어회무침', '입맛 없을 때는 새콤달콤한 전어회무침이 최고에요. 입안에 군침이 좌르르 돌아요.', 30, '초보환영', 2, '나물/생채/샐러드', '한식', '187Kcal', '농림수산식품교육문화정보원', 2),
(462, 'r462', '왕새우구이와구운채소', '각종 허브오일에 마리네이드한 왕새우를 오븐에 먹기좋게 구워 톡쏘는 와사비감자와 즐겨보세요.', 40, '보통', 2, '구이', '서양', '285Kcal', '농림수산식품교육문화정보원', 2),
(463, 'r463', '소꼬리찜', '몸이 허하다고 생각이 들때는 소꼬리찜으로 원기회복해 보세요. 국물이 있어서 해장에도 아주 좋아요.', 60, '초보환영', 2, '찜', '한식', '457Kcal', '농림수산식품교육문화정보원', 3),
(464, 'r464', '삼색나물월남쌈', '삼색나물과 고기산적을 각종 채소들과 함께 부드러운 라이스 페이퍼에 싸드세요. 세가지 소스중에 무엇을 찍어먹을지 행복한 고민을 해볼까요.', 30, '보통', 2, '나물/생채/샐러드', '퓨전', '251Kcal', '농림수산식품교육문화정보원', 2),
(465, 'r465', '토란닭고기찜', '닭고기 살에 적당히 배인 간장소스가 너무나도 맛있는거 있죠. 담백한 토란과 함께 즐겨줘요.', 30, '보통', 2, '찜', '한식', '310Kcal', '농림수산식품교육문화정보원', 3),
(466, 'r466', '녹두고물호박떡케이크', '은은한 연두색 녹두고물이 덮인 호박떡케이크랍니다. 설탕은 조금만 첨가시키고 단호박의 자연적인 단맛을 즐겨보세요.', 70, '어려움', 2, '떡/한과', '한식', '264Kcal', '농림수산식품교육문화정보원', 2),
(467, 'r467', '크림소스파스타', '남녀노소 좋아하는 크림파스타! 이젠 집에서도 즐겨보세요~', 60, '보통', 2, '만두/면류', '이탈리아', '350Kcal', '농림수산식품교육문화정보원', 1),
(468, 'r468', '상추미소국', '냉장고에 먹다 남은 상추 있으신가요? 그럼 시원한 미소국에 한 번 넣어보세요~ 상추의 향과 미소된장의 향이 아주 잘 어울려요!', 20, '초보환영', 2, '국', '일본', '53Kcal', '농림수산식품교육문화정보원', 3),
(469, 'r469', '가지김치', '오늘은 아삭한 가지로 만든 김치! 과연 어떤 맛일까요?', 30, '초보환영', 2, '밑반찬/김치', '한식', '45Kcal', '농림수산식품교육문화정보원', 4),
(470, 'r470', '버섯잡채', '당면 대신 버섯을 이용해 고소한 잡채를 만들어 보세요.', 30, '초보환영', 2, '볶음', '한식', '201Kcal', '농림수산식품교육문화정보원', 2),
(471, 'r471', '부추올리브오일무침', '기름기가 없어 질겨지거나 퍽퍽할 수 있는 부추무침에 올리브오일을 첨가해 보세요. 윤기가 흐르는 부추무침을 보면 입맛이 돌아와요.', 20, '초보환영', 2, '나물/생채/샐러드', '퓨전', '43Kcal', '농림수산식품교육문화정보원', 2),
(472, 'r472', '바베큐립', '패밀리레스토랑의 맛을 재현하다~ 그 맛이 바로 바비큐립!', 60, '보통', 2, '구이', '서양', '241Kcal', '농림수산식품교육문화정보원', 2),
(473, 'r473', '무쌈말이', '비트로 물을 들여 색깔이 아주 화려하답니다. 온갖 채소들을 돌돌 말아 특히 여성분들에게 좋아요', 30, '초보환영', 2, '나물/생채/샐러드', '한식', '110Kcal', '농림수산식품교육문화정보원', 2),
(474, 'r474', '치킨샐러드', '느끼하지 않은 닭가슴살로 만든 샐러드랍니다. 달콤한 허니머스터드를 뿌려드세요!', 30, '초보환영', 2, '나물/생채/샐러드', '서양', '295Kcal', '농림수산식품교육문화정보원', 2),
(475, 'r475', '된장채소수제비', '된장은 음식의 간과 맛을 보태주는 역할과 함께 식물성 단백질로 구성되어 버릴 것 하나 없는 기특한 식품입니다.', 30, '초보환영', 2, '만두/면류', '한식', '350Kcal', '농림수산식품교육문화정보원', 1),
(476, 'r476', '고추장닭강정', '고추장으로 매콤 달콤하게 맛을 낸 닭강정을 만들어보세요..모두가 즐길 수 있는 요리랍니다.', 40, '보통', 2, '튀김/커틀릿', '퓨전', '385Kcal', '농림수산식품교육문화정보원', 2),
(477, 'r477', '참치죽', '고소한 참치가 들어가 심심하지 않아요~', 30, '초보환영', 2, '밥', '한식', '296Kcal', '농림수산식품교육문화정보원', 1),
(478, 'r478', '두부파프리카전', '고소한 두부의 맛을 살려주는 포도씨유로 두부 파프리카전을 지져보세요. 느끼하지 않은 기름이 음식맛을 살려준답니다~', 30, '초보환영', 2, '부침', '한식', '96Kcal', '농림수산식품교육문화정보원', 2),
(479, 'r479', '고추잡채와꽃빵', '매콤한 고추잡채에 쫄깃한 꽃빵을 곁들여 드셔보세요~', 30, '초보환영', 2, '만두/면류', '중국', '110Kcal', '농림수산식품교육문화정보원', 1),
(480, 'r480', '해물찌개', '개운한 국물 한술 뜨면 피로가 싹 날아가는 시원한 해물찌개~ 쌀쌀한 날씨엔 시원한 국물이 최고랍니다!', 30, '보통', 4, '찌개/전골/스튜', '한식', '165Kcal', '농림수산식품교육문화정보원', 3),
(481, 'r481', '돼지고기김치찌개', '개운한 김치찌개~! 신김치와 청정원 국선생 육수만  있으면 감칠맛 나는 요리는 문제 없답니다.', 30, '보통', 4, '찌개/전골/스튜', '한식', '120Kcal', '농림수산식품교육문화정보원', 3),
(482, 'r482', '두부조림', '바삭한 두부를 감칠맛나는 굴소스에 부드럽게 조렸어요~ 술안주로 밥반찬으로 인기 만점이에요!', 30, '초보환영', 4, '조림', '한식', '108Kcal', '농림수산식품교육문화정보원', 4),
