(120463, 'r120463', '당근잎 감자전', '당근 향이 나는 향긋한 당근잎 감자전', 20, '보통', 2, '부침', '한식', '0Kcal', '농림수산식품교육문화정보원', 2),
(120476, 'r120476', '배추만두', '배추로 만든 깜찍한 배추주머니 만두! 아삭한 배추와 영양으로 가~득 채운 보기도 좋고 맛도 좋은 배추만두랍니다.', 30, '보통', 2, '찜', '한식', '0Kcal', '농림수산식품교육문화정보원', 3),
(180330, 'r180330', '식빵고구마파이', '식빵을 이용한 간단 고구마파이! 아이들 영양 간식으로 딱!', 30, '초보환영', 2, '빵/과자', '서양', '0Kcal', '농림수산식품교육문화정보원', 3),
(180344, 'r180344', '카레토마토달걀볶음밥', '토마토와 달걀을 넣은 볶음밥에 카레소스를 두른 영양만점 볶음밥', 30, '초보환영', 1, '밥', '퓨전', '0Kcal', '농림수산식품교육문화정보원', 1),
(180363, 'r180363', '쪽파 새우강회', '새우에 쪽파를 감아 간단하게 만들지만 새우와 쪽파의 달콤한 맛과 새콤한 초고추장의 환상의 콤비! 거기에 건강까지 좋은 영양만점 쪽파 새우강회!!', 20, '초보환영', 2, '나물/생채/샐러드', '퓨전', '0Kcal', '농림수산식품교육문화정보원', 2),
(195428, 'r195428', '누드김밥', '건강한 재료로 가득담아 말은 누드김밥! 고기가 없어도 맛있어요!!', 20, '보통', 3, '밥', '퓨전', '0Kcal', '농림수산식품교육문화정보원', 1),
(195453, 'r195453', '콩비지동그랑땡', '두부대신 콩비지를 넣어 만든 동그랑땡 맛도 좋아요!', 30, '보통', 3, '부침', '한식', '0Kcal', '농림수산식품교육문화정보원', 2),
