(180363, 5, '새우에 쪽파를 감아 접시에 담아 준다.'),
(195428, 1, '당근과 오이는 얇게 슬라이스 해준다. 가지는 길게 잘라준다.'),
(195428, 2, '오이를 제외한 당근과 가지를 기름 두른 팬에 볶아준다. (팁: 가지는 간장으로 당근은 소금으로 간을 해준다.)'),
