(195428, 9, '믹서기에 두부, 식초, 설탕, 마요네즈, 통깨를 넣고 갈아 두부드레싱을 만들어 준다.'),
(195428, 10, '접시에 담긴 김밥위에 두부 드레싱을 뿌려준다.'),
(195453, 1, '대파, 호박, 배추는 작게 다져준다.'),
(195453, 2, '볼에 콩비지와 고기, 다진 채소, 다진마늘, 후추, 소금, 참기름을 넣어준다.'),
(195453, 3, '부침가루와 전분을 넣고 계란 1개를 넣어 반죽하듯 잘 섞어준다.'),
